use chrono::{NaiveDate, NaiveDateTime, NaiveTime};
fn try_all(s: &str) {
    let mut res = String::new();
    if let Ok(d) = NaiveDate::parse_from_str(s, "%Y-%m-%d") { res.push_str(&format!("DATE:{:?} ", d)); }
    if let Ok(d) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S%.f") { res.push_str(&format!("DTSP:{:?} ", d)); }
    if let Ok(d) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f") { res.push_str(&format!("DTT:{:?} ", d)); }
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M:%S%.f") { res.push_str(&format!("TIME:{:?} ", t)); }
    if res.is_empty() { res.push_str("NONE "); }
    println!("{:40} {}", s, res);
}
fn main() {
    for s in ["2024-01-02T10:20:30", "2024-01-02", "2024-01-02 10:20:30", "2024-01-02 10:20:30Z", "2024-01-02T10:20:30Z", "2024-01-02 10:20", "2024-01-02 10:20:30.123", "2024-1-1", "1700000000"] { try_all(s); }
}
EOF
cargo run --offline -q 2>&1 | head -20"}

