use chrono::{NaiveDate, NaiveDateTime, NaiveTime};
fn t(s: &str, f: &str, name: &str) {
    let r = NaiveDate::parse_from_str(s, f);
    println!("{name} {s:?} -> {r:?}");
}
fn d(s: &str, f: &str, name: &str) {
    let r = NaiveDateTime::parse_from_str(s, f);
    println!("{name} {s:?} -> {r:?}");
}
fn main() {
    for s in ["2024-01-02x","2024-01-02 "," 2024-01-02","2024-01-0x","2024-1-1","1700000000","2024-13-45","2024-01-02T10:20:30"] {
        t(s, "%Y-%m-%d", "DATE");
    }
    for s in ["2024-01-02 10:20:30 extra","2024-01-02 10:20:30.5 ","2024-01-02 T10:20:30","2024-01-02-10:20"] {
        d(s, "%Y-%m-%d %H:%M:%S%.f", "DTSP");
    }
    println!("--- timedate split");
    for (s,f) in [("2024-01-02", "%Y-%m-%d"),("10:20:30 extra","%H:%M:%S%.f"),("T10:20:30","%H:%M:%S%.f"),("10:20:30.5 ","%H:%M:%S%.f"),("-10:20","%H:%M:%S%.f")] {
        let r = if f.starts_with("%H") { NaiveTime::parse_from_str(s,f) } else { NaiveDate::parse_from_str(s,f).map(|x| x.to_string()).map_err(|e|e) };
        println!("{s:?} -> {r:?}");
    }
}
EOF
cargo run --offline -q 2>&1 | head -30"}

