import os
def walk(root):
    out=[]
    for d,_,fs in os.walk(root):
        for f in fs:
            rel=os.path.relpath(os.path.join(d,f), root).replace('\\','/')
            out.append(rel)
    return sorted(out)
static=walk('src/assets/static'); tstatic=walk('src/assets/theme_static')
tpl=sorted(os.listdir('src/assets/templates')); ttpl=sorted(os.listdir('src/assets/theme_templates'))
def key(p): return p.replace('/','_').replace('.','_').replace('-','_')
out=['// Embedded assets (templates, static files) that the original ships inside its binary.']
out.append('pub const STATIC: &[(&str, &[u8])] = &[')
for p in static:
    path='src/assets/static/'+p
    if p.endswith(('.png','.ico','.woff','.jpg','.jpeg','.gif','.webp')):
        out.append(f'    ("{p}", include_bytes!("{path}")),')
    else:
        out.append(f'    ("{p}", include_str!("{path}").as_bytes()),')
out.append('];\n')
out.append('pub const THEME_STATIC: &[(&str, &[u8])] = &[')
for p in tstatic:
    path='src/assets/theme_static/'+p
    if p.endswith(('.png','.ico','.woff','.jpg','.jpeg','.gif','.webp')):
        out.append(f'    ("{p}", include_bytes!("{path}")),')
    else:
        out.append(f'    ("{p}", include_str!("{path}").as_bytes()),')
out.append('];\n')
out.append('pub const TEMPLATES: &[(&str, &str)] = &[')
for p in tpl: out.append(f'    ("{p}", include_str!("assets/templates/{p}")),')
out.append('];\n')
out.append('pub const THEME_TEMPLATES: &[(&str, &str)] = &[')
for p in ttpl: out.append(f'    ("{p}", include_str!("assets/theme_templates/{p}")),')
out.append('];\n')
out.append('pub const THEME_README: &str = include_str!("assets/theme_README.md");')
out.append('pub const THEME_JSON: &str = include_str!("assets/theme_theme.json");')
out.append('pub const GENERATE_CONFIG: &str = include_str!("assets/generate_config.yaml");')
out.append('pub const INIT_CONTENT: &[(&str, &str)] = &[')
for f in sorted(os.listdir('src/assets/init_content')):
    if os.path.isfile('src/assets/init_content/'+f):
        out.append(f'    ("{f}", include_str!("assets/init_content/{f}")),')
out.append('];')
out.append('pub const INIT_CUSTOM_CSS: &str = include_str!("assets/init_site/custom.css");')
out.append('pub const INIT_CUSTOM_JS: &str = include_str!("assets/init_site/custom.js");')
open('src/embedded.rs','w').write('\n'.join(out)+'\n')
PY
head -8 src/embedded.rs; wc -l src/embedded.rs; ls src/assets/init_content | head"}

