use std::io::Write;
use std::sync::atomic::{AtomicUsize, Ordering};
use chrono::{Datelike, Timelike, Utc};

pub static LEVEL: AtomicUsize = AtomicUsize::new(3); // 0=off 1=error 2=warn 3=info 4=debug 5=trace

pub fn set_level(n: usize) {
    LEVEL.store(n, Ordering::Relaxed);
}
pub fn level() -> usize {
    LEVEL.load(Ordering::Relaxed)
}

pub fn level_from_verbosity(v: u8) -> usize {
    match v {
        0 => 2,
        1 => 3,
        2 => 4,
        3 => 5,
        _ => 5,
    }
}

/// Parse RUST_LOG env var into a max level, applying a target filter.
pub fn level_from_env(spec: &str, target: &str) -> usize {
    // Very small subset of env_logger's filter syntax: handles "level",
    // "target=level", "target", comma separated.
    let mut max = 0usize;
    for part in spec.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let (tgt, lvl) = match part.split_once('=') {
            Some((t, l)) => (t.trim().to_string(), parse_level(l.trim())),
            None => {
                if parse_level(part).is_some() {
                    (String::new(), parse_level(part).unwrap())
                } else {
                    (part.to_string(), 5)
                }
            }
        };
        let matches = tgt.is_empty()
            || target == tgt
            || target.starts_with(&format!("{}.", tgt));
        if matches && lvl > max {
            max = lvl;
        }
    }
    max
}

fn parse_level(s: &str) -> Option<usize> {
    match s.to_lowercase().as_str() {
        "off" => Some(0),
        "error" => Some(1),
        "warn" => Some(2),
        "info" => Some(3),
        "debug" => Some(4),
        "trace" => Some(5),
        _ => None,
    }
}

pub fn level_name(n: usize) -> &'static str {
    match n {
        1 => "ERROR",
        2 => "WARN",
        3 => "INFO",
        4 => "DEBUG",
        5 => "TRACE",
        _ => "OFF",
    }
}

fn timestamp() -> String {
    let now = Utc::now();
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        now.year(),
        now.month(),
        now.day(),
        now.hour(),
        now.minute(),
        now.second()
    )
}

pub fn log(lvl: usize, target: &str, msg: &str) {
    if lvl == 0 || lvl > level() {
        return;
    }
    let err = std::io::stderr();
    let mut lock = err.lock();
    let _ = writeln!(
        lock,
        "[{} {:<5} {}] {}",
        timestamp(),
        level_name(lvl),
        target,
        msg
    );
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => { crate::logger::log(1, $target, &format!($($arg)*)) };
}
