{"command": "cd /tmp/marmite && cat > src/markdown.rs <<'RSEOF'
// A CommonMark-ish renderer producing the same HTML as the reference binary.
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Block {
    Paragraph(Vec<Inline>),
    Heading(u8, Vec<Inline>),
    CodeBlock { info: String, text: String, fenced: bool },
    HtmlBlock(String),
    ThematicBreak,
    BlockQuote(Vec<Block>),
    List(ListData),
    Table(TableData),
    DefinitionList(Vec<DefEntry>),
    FootnoteDef(String, Vec<Block>),
    Empty,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ListData {
    pub ordered: bool,
    pub start: u32,
    pub tight: bool,
    pub items: Vec<Vec<Block>>,
    pub tasks: Vec<Option<bool>>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TableData {
    pub aligns: Vec<u8>, // 0 none, 1 left, 2 right, 3 center
    pub head: Vec<Vec<Inline>>,
    pub rows: Vec<Vec<Vec<Inline>>>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct DefEntry {
    pub term: Option<Vec<Inline>>,
    pub definition: Vec<Vec<Inline>>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Inline {
    Text(String),
    SoftBreak,
    HardBreak,
    Code(String),
    Emph(Vec<Inline>),
    Strong(Vec<Inline>),
    Del(Vec<Inline>),
    Uline(Vec<Inline>),
    Link { dest: String, title: Option<String>, children: Vec<Inline> },
    Image { dest: String, alt: Vec<Inline>, title: Option<String> },
    Autolink { url: String, text: String },
    Html(String),
    FootnoteRef(usize),
    TaskMarker(bool),
}

pub struct LinkRefs {
    pub map: HashMap<String, (String, Option<String>)>,
}

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

pub struct Renderer {
    out: String,
}

impl Renderer {
    fn new() -> Self {
        Renderer { out: String::new() }
    }
    fn cr(&mut self) {
        if !self.out.is_empty() && !self.out.ends_with('\n') {
            self.out.push('\n');
        }
    }
    fn lit(&mut self, s: &str) {
        self.out.push_str(s);
    }
    fn inline(&mut self, inl: &[Inline]) {
        for i in inl {
            self.render_inline(i);
        }
    }
    fn render_inline(&mut self, i: &Inline) {
        match i {
            Inline::Text(t) => self.lit(&escape_html(t)),
            Inline::SoftBreak => self.lit("\n"),
            Inline::HardBreak => self.lit("<br />\n"),
            Inline::Code(c) => {
                self.lit("<code>");
                self.lit(&escape_html(c));
                self.lit("</code>");
            }
            Inline::Emph(c) => {
                self.lit("<em>");
                self.inline(c);
                self.lit("</em>");
            }
            Inline::Strong(c) => {
                self.lit("<strong>");
                self.inline(c);
                self.lit("</strong>");
            }
            Inline::Del(c) => {
                self.lit("<del>");
                self.inline(c);
                self.lit("</del>");
            }
            Inline::Uline(c) => {
                self.lit("<u>");
                self.inline(c);
                self.lit("</u>");
            }
            Inline::Link { dest, title, children } => {
                let href = super::links::to_url(dest);
                self.lit("<a href=\"");
                self.lit(&escape_html(&href));
                if let Some(t) = title {
                    self.lit("\" title=\"");
                    self.lit(&escape_html(t));
                }
                self.lit("\">");
                self.inline(children);
                self.lit("</a>");
            }
            Inline::Image { dest, alt, title } => {
                self.lit("<figure><img src=\"");
                self.lit(&escape_html(dest));
                self.lit("\" alt=\"");
                self.lit(&escape_html(&alt_text(alt)));
                if let Some(t) = title {
                    self.lit("\" title=\"");
                    self.lit(&escape_html(t));
                }
                self.lit("\" />");
                if let Some(t) = title {
                    self.lit("<figcaption>");
                    self.lit(&escape_html(t));
                    self.lit("</figcaption>");
                }
                self.lit("</figure>");
            }
            Inline::Autolink { url, text } => {
                self.lit("<a href=\"");
                self.lit(&escape_html(url));
                self.lit("\">");
                self.lit(&escape_html(text));
                self.lit("</a>");
            }
            Inline::Html(h) => self.lit(h),
            Inline::FootnoteRef(n) => {
                self.lit(&format!(
                    "<sup class=\"footnote-ref\"><a href=\"#fn-{n}\" id=\"fnref-{n}\" data-footnote-ref>{n}</a></sup>"
                ));
            }
            Inline::TaskMarker(done) => {
                if *done {
                    self.lit("<input type=\"checkbox\" checked=\"\" disabled=\"\" /> ");
                } else {
                    self.lit("<input type=\"checkbox\" disabled=\"\" /> ");
                }
            }
        }
    }

    fn block(&mut self, b: &Block, tight: bool, footnotes: &mut Vec<(usize, Vec<Block>)>) {
        match b {
            Block::Empty => {}
            Block::Paragraph(inl) => {
                if tight {
                    self.inline(inl);
                } else {
                    self.cr();
                    self.lit("<p>");
                    self.inline(inl);
                    self.lit("</p>");
                    self.cr();
                }
            }
