fn alt_text(inl: &[Inline]) -> String {
    let mut s = String::new();
    for i in inl {
        match i {
            Inline::Text(t) => s.push_str(t),
            Inline::SoftBreak | Inline::HardBreak => s.push(' '),
            Inline::Code(c) => s.push_str(c),
            Inline::Emph(c) | Inline::Strong(c) | Inline::Del(c) | Inline::Uline(c) => {
                s.push_str(&alt_text(c))
            }
            Inline::Link { children, .. } => s.push_str(&alt_text(children)),
            Inline::Image { alt, .. } => s.push_str(&alt_text(alt)),
            Inline::Autolink { text, .. } => s.push_str(text),
            Inline::Html(h) => s.push_str(h),
            Inline::FootnoteRef(n) => s.push_str(&n.to_string()),
            Inline::TaskMarker(_) => {}
        }
    }
    s
}

fn align_attr(a: u8) -> &'static str {
    match a {
        1 => " align=\"left\"",
        2 => " align=\"right\"",
        3 => " align=\"center\"",
        _ => "",
    }
}

/// Slug used for heading anchors.
pub fn anchor_slug(text: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = false;
    for c in text.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
            prev_dash = false;
        } else if !prev_dash {
            out.push('-');
            prev_dash = true;
        }
    }
    let trimmed = out.trim_matches('-');
    if trimmed.is_empty() {
        "section".to_string()
    } else {
        trimmed.to_string()
    }
}

/// Render a parsed document into HTML.
pub fn render(blocks: &[Block], footnotes: &[(usize, Vec<Block>)]) -> String {
    let mut r = Renderer::new();
    let mut fns: Vec<(usize, Vec<Block>)> = footnotes.to_vec();
    for b in blocks {
        r.block(b, false, &mut fns);
    }
    if !fns.is_empty() {
        r.cr();
        r.lit("<section class=\"footnotes\" data-footnotes>");
        r.cr();
        r.lit("<ol>");
        for (n, body) in &fns {
            r.cr();
            r.lit(&format!("<li id=\"fn-{n}\">"));
            for c in body {
                r.block(c, false, &mut Vec::new());
            }
            r.cr();
            r.lit(&format!(
