            Inline::HardBreak => self.lit("<br />\n"),
            Inline::Code(c) => {
                self.lit("<code>");
                self.lit(&escape_html(c));
                self.lit("</code>");
            }
            Inline::Emph(c) => {
                self.lit("<em>");
                self.inline(c);
                self.lit("</em>");
            }
            Inline::Strong(c) => {
                self.lit("<strong>");
                self.inline(c);
                self.lit("</strong>");
            }
            Inline::Del(c) => {
                self.lit("<del>");
                self.inline(c);
                self.lit("</del>");
            }
            Inline::Uline(c) => {
                self.lit("<u>");
                self.inline(c);
                self.lit("</u>");
            }
            Inline::Link { dest, title, children } => {
                let href = super::links::to_url(dest);
                self.lit("<a href=\"");
                self.lit(&escape_html(&href));
                if let Some(t) = title {
                    self.lit("\" title=\"");
                    self.lit(&escape_html(t));
                }
                self.lit("\">");
                self.inline(children);
                self.lit("</a>");
            }
            Inline::Image { dest, alt, title } => {
                self.lit("<figure><img src=\"");
                self.lit(&escape_html(dest));
                self.lit("\" alt=\"");
                self.lit(&escape_html(&alt_text(alt)));
                if let Some(t) = title {
                    self.lit("\" title=\"");
                    self.lit(&escape_html(t));
                }
                self.lit("\" />");
                if let Some(t) = title {
                    self.lit("<figcaption>");
                    self.lit(&escape_html(t));
                    self.lit("</figcaption>");
                }
                self.lit("</figure>");
            }
            Inline::Autolink { url, text } => {
                self.lit("<a href=\"");
                self.lit(&escape_html(url));
                self.lit("\">");
                self.lit(&escape_html(text));
                self.lit("</a>");
            }
            Inline::Html(h) => self.lit(h),
            Inline::FootnoteRef(n) => {
                self.lit(&format!(
                    "<sup class=\"footnote-ref\"><a href=\"#fn-{n}\" id=\"fnref-{n}\" data-footnote-ref>{n}</a></sup>"
                ));
            }
            Inline::TaskMarker(done) => {
                if *done {
                    self.lit("<input type=\"checkbox\" checked=\"\" disabled=\"\" /> ");
                } else {
                    self.lit("<input type=\"checkbox\" disabled=\"\" /> ");
                }
            }
        }
    }

    fn block(&mut self, b: &Block, tight: bool, footnotes: &mut Vec<(usize, Vec<Block>)>) {
        match b {
            Block::Empty => {}
            Block::Paragraph(inl) => {
                if tight {
                    self.inline(inl);
                } else {
                    self.cr();
                    self.lit("<p>");
                    self.inline(inl);
                    self.lit("</p>");
                    self.cr();
                }
            }
            Block::Heading(level, inl) => {
                self.cr();
                let text = alt_text(inl);
                let anchor = anchor_slug(&text);
                self.lit(&format!(
                    "<h{level}><a href=\"#{anchor}\" aria-hidden=\"true\" class=\"anchor\" id=\"{anchor}\"></a>"
                ));
                self.inline(inl);
                self.lit(&format!("</h{level}>"));
                self.cr();
            }
            Block::CodeBlock { info, text, fenced } => {
                self.cr();
                if *fenced && !info.is_empty() {
                    let lang = info.split_whitespace().next().unwrap_or("");
                    self.lit(&format!(
                        "<pre><code class=\"language-{}\">",
                        escape_html(lang)
                    ));
                } else {
                    self.lit("<pre><code>");
                }
                self.lit(&escape_html(text));
                self.lit("</code></pre>");
                self.cr();
            }
            Block::HtmlBlock(raw) => {
                self.cr();
                self.lit(raw);
                self.cr();
            }
            Block::ThematicBreak => {
                self.cr();
                self.lit("<hr />");
                self.cr();
            }
            Block::BlockQuote(children) => {
                self.cr();
                self.lit("<blockquote>");
                for c in children {
                    self.block(c, false, footnotes);
                }
                self.lit("</blockquote>");
                self.cr();
            }
            Block::List(list) => {
                self.cr();
                if list.ordered {
                    if list.start != 1 {
                        self.lit(&format!("<ol start=\"{}\">", list.start));
                    } else {
                        self.lit("<ol>");
                    }
                } else {
                    self.lit("<ul>");
                }
                for (idx, children) in list.items.iter().enumerate() {
                    self.cr();
                    let task = list.tasks.get(idx).cloned().flatten();
                    if let Some(done) = task {
                        if done {
                            self.lit("<li><input type=\"checkbox\" checked=\"\" disabled=\"\" /> ");
                        } else {
                            self.lit("<li><input type=\"checkbox\" disabled=\"\" /> ");
                        }
                    } else {
                        self.lit("<li>");
                    }
                    let first_is_para = matches!(children.first(), Some(Block::Paragraph(_)));
                    if list.tight && first_is_para && children.len() > 0 {
                        if children.len() == 1 {
                            if let Some(Block::Paragraph(inl)) = children.first() {
                                self.inline(inl);
                            }
                        } else {
                            if let Some(Block::Paragraph(inl)) = children.first() {
                                self.inline(inl);
                            }
                            for c in &children[1..] {
                                self.block(c, false, footnotes);
                            }
                        }
                    } else {
                        if !children.is_empty() {
                            self.cr();
                        }
                        for c in children {
                            self.block(c, false, footnotes);
                        }
                    }
                    self.lit("</li>");
                    self.cr();
                }
                if list.ordered {
                    self.lit("</ol>");
                } else {
                    self.lit("</ul>");
                }
                self.cr();
            }
            Block::Table(t) => {
                self.cr();
                self.lit("<table>");
                self.cr();
                self.lit("<thead>");
                self.cr();
                self.lit("<tr>");
                for (i, cell) in t.head.iter().enumerate() {
                    self.cr();
                    let al = align_attr(t.aligns.get(i).copied().unwrap_or(0));
                    self.lit(&format!("<th{al}>"));
                    self.inline(cell);
                    self.lit("</th>");
                }
                self.cr();
                self.lit("</tr>");
                self.cr();
                self.lit("</thead>");
                if !t.rows.is_empty() {
                    self.cr();
                    self.lit("<tbody>");
                    for row in &t.rows {
                        self.cr();
                        self.lit("<tr>");
                        for (i, cell) in row.iter().enumerate() {
                            self.cr();
                            let al = align_attr(t.aligns.get(i).copied().unwrap_or(0));
                            self.lit(&format!("<td{al}>"));
                            self.inline(cell);
                            self.lit("</td>");
                        }
                        self.cr();
                        self.lit("</tr>");
                    }
                    self.cr();
                    self.lit("</tbody>");
                }
                self.cr();
                self.lit("</table>");
                self.cr();
            }
            Block::DefinitionList(entries) => {
                self.cr();
                self.lit("<dl>");
                for e in entries {
                    if let Some(term) = &e.term {
                        self.cr();
                        self.lit("<dt>");
                        self.inline(term);
                        self.lit("</dt>");
                    }
                    for d in &e.definition {
                        self.cr();
                        self.lit("<dd>");
                        self.inline(d);
                        self.lit("</dd>");
                    }
                }
                self.cr();
                self.lit("</dl>");
                self.cr();
            }
            Block::FootnoteDef(_, _) => {}
        }
    }
}

fn alt_text(inl: &[Inline]) -> String {
    let mut s = String::new();
    for i in inl {
        match i {
            Inline::Text(t) => s.push_str(t),
            Inline::SoftBreak | Inline::HardBreak => s.push(' '),
            Inline::Code(c) => s.push_str(c),
            Inline::Emph(c) | Inline::Strong(c) | Inline::Del(c) | Inline::Uline(c) => {
                s.push_str(&alt_text(c))
            }
            Inline::Link { children, .. } => s.push_str(&alt_text(children)),
            Inline::Image { alt, .. } => s.push_str(&alt_text(alt)),
            Inline::Autolink { text, .. } => s.push_str(text),
            Inline::Html(h) => s.push_str(h),
            Inline::FootnoteRef(n) => s.push_str(&n.to_string()),
            Inline::TaskMarker(_) => {}
        }
    }
    s
}

fn align_attr(a: u8) -> &'static str {
    match a {
        1 => " align=\"left\"",
        2 => " align=\"right\"",
        3 => " align=\"center\"",
        _ => "",
    }
}

/// Slug used for heading anchors.
pub fn anchor_slug(text: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = false;
    for c in text.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
            prev_dash = false;
        } else if !prev_dash {
            out.push('-');
            prev_dash = true;
        }
    }
    let trimmed = out.trim_matches('-');
    if trimmed.is_empty() {
        "section".to_string()
    } else {
        trimmed.to_string()
    }
}

/// Render a parsed document into HTML.
pub fn render(blocks: &[Block], footnotes: &[(usize, Vec<Block>)]) -> String {
    let mut r = Renderer::new();
    let mut fns: Vec<(usize, Vec<Block>)> = footnotes.to_vec();
    for b in blocks {
        r.block(b, false, &mut fns);
    }
    if !fns.is_empty() {
        r.cr();
        r.lit("<section class=\"footnotes\" data-footnotes>");
        r.cr();
        r.lit("<ol>");
        for (n, body) in &fns {
            r.cr();
            r.lit(&format!("<li id=\"fn-{n}\">"));
            for c in body {
                r.block(c, false, &mut Vec::new());
            }
            r.cr();
            r.lit(&format!(
                "<a href=\"#fnref-{n}\" class=\"footnote-backref\" data-footnote-backref data-footnote-backref-idx=\"{n}\" aria-label=\"Back to reference {n}\">\u{21a9}</a>"
            ));
            r.cr();
            r.lit("</li>");
        }
        r.cr();
        r.lit("</ol>");
        r.cr();
        r.lit("</section>");
        r.cr();
    }
    r.out
}
