// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

struct Line<'a> {
    raw: &'a str,
    indent: usize, // number of leading spaces
    content: &'a str,
    blank: bool,
}

fn scan_line(raw: &str) -> Line {
    let indent = raw.len() - raw.trim_start_matches(' ').len();
    let content = &raw[indent.min(raw.len())..];
    let blank = content.trim().is_empty();
    Line { raw, indent, content, blank }
}

fn is_thematic_break(content: &str) -> bool {
    let c = content.trim();
    if c.len() < 3 {
        return false;
    }
    let ch = c.chars().next().unwrap();
    if ch != '*' && ch != '-' && ch != '_' {
        return false;
    }
    let mut n = 0;
    for x in c.chars() {
        if x == ch {
            n += 1;
        } else if x == ' ' || x == '\t' {
        } else {
            return false;
        }
    }
    n >= 3
}

fn atx_heading(content: &str) -> Option<(u8, String)> {
    let c = content;
    let hashes = c.chars().take_while(|x| *x == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let rest = &c[hashes..];
    if rest.is_empty() {
        return Some((hashes as u8, String::new()));
    }
    if !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }
    let mut text = rest.trim_start().to_string();
    // strip closing sequence
    let trimmed = text.trim_end();
    if let Some(idx) = trimmed.rfind('#') {
        let tail = &trimmed[idx..];
        if tail.chars().all(|x| x == '#') && tail.len() > 0 {
            let before = trimmed[..idx].chars().last();
            if before.is_none() || before == Some(' ') || before == Some('\t') {
                text = trimmed[..idx].trim_end().to_string();
            }
        }
    }
    Some((hashes as u8, text))
}

fn fence(content: &str) -> Option<(char, usize, String)> {
    let c = content;
    let ch = c.chars().next()?;
    if ch != '`' && ch != '~' {
        return None;
    }
    let n = c.chars().take_while(|x| *x == ch).count();
    if n < 3 {
        return None;
    }
    let info = c[n..].trim().to_string();
    if ch == '`' && info.contains('`') {
        return None;
    }
    Some((ch, n, info))
}

fn list_marker(content: &str) -> Option<(bool, u32, usize, bool)> {
    // returns (ordered, number, marker_len, has_space_after)
    let bytes = content.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (ordered, num, len) = if bytes[0] == b'-' || bytes[0] == b'+' || bytes[0] == b'*' {
        (false, 1u32, 1usize)
    } else if bytes[0].is_ascii_digit() {
        let mut i = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() && i < 10 {
            i += 1;
        }
        if i >= bytes.len() {
            return None;
        }
        if bytes[i] != b'.' && bytes[i] != b')' {
            return None;
        }
        let num: u32 = content[..i].parse().ok()?;
        (true, num, i + 1)
    } else {
        return None;
    };
    if len >= content.len() {
        return Some((ordered, num, len, false));
    }
    let after = &content[len..];
    if after.starts_with(' ') || after.starts_with('\t') {
        Some((ordered, num, len, true))
    } else if after.is_empty() {
        Some((ordered, num, len, false))
    } else {
        None
    }
}

fn task_marker(content: &str) -> Option<(bool, usize)> {
    // content starts after the list marker + space
    if content.starts_with("[ ] ") {
        Some((false, 4))
    } else if content.starts_with("[x] ") || content.starts_with("[X] ") {
        Some((true, 4))
    } else if content.starts_with("[ ]\t") {
        Some((false, 4))
    } else {
        None
    }
}

pub struct Parsed {
    pub blocks: Vec<Block>,
    pub footnotes: Vec<(usize, Vec<Block>)>,
    pub link_refs: LinkRefs,
}

pub fn parse(src: &str) -> Parsed {
    let lines: Vec<Line> = src.split('\n').map(scan_line).collect();
    let mut p = Parser {
        lines,
        i: 0,
        blocks: Vec::new(),
        footnotes: Vec::new(),
        foot_order: Vec::new(),
        link_refs: LinkRefs {
            map: HashMap::new(),
        },
    };
    p.parse_blocks(0, false);
    Parsed {
        blocks: p.blocks,
        footnotes: p.footnotes,
        link_refs: p.link_refs,
    }
}

struct Parser<'a> {
    lines: Vec<Line<'a>>,
    i: usize,
    blocks: Vec<Block>,
    footnotes: Vec<(usize, Vec<Block>)>,
    foot_order: Vec<String>,
    link_refs: LinkRefs,
}

impl<'a> Parser<'a> {
    fn cur(&self) -> Option<&Line<'a>> {
        self.lines.get(self.i)
    }
    fn at(&self, k: usize) -> Option<&Line<'a>> {
        self.lines.get(self.i + k)
    }
    fn parse_blocks(&mut self, min_indent: usize, in_list_item: bool) -> Vec<Block> {
        let mut out = Vec::new();
        loop {
            let line = match self.cur() {
                Some(l) => l,
                None => break,
            };
            if line.blank {
                self.i += 1;
                continue;
            }
            if line.indent < min_indent {
                break;
            }
            let c = line.content;
            // thematic break
            if is_thematic_break(c) {
                self.i += 1;
                out.push(Block::ThematicBreak);
                continue;
            }
            // ATX heading
            if let Some((lvl, text)) = atx_heading(c) {
                self.i += 1;
                out.push(Block::Heading(lvl, parse_inlines(&text, &self.link_refs)));
                continue;
            }
            // fenced code
            if let Some((ch, n, info)) = fence(c) {
                let start = self.i;
                self.i += 1;
                let mut body: Vec<String> = Vec::new();
                let mut closed = false;
                while let Some(l) = self.cur() {
                    let lc = l.content;
                    let ind = l.indent.min(3);
                    let stripped = &l.raw[ind.min(l.raw.len())..];
                    if let Some((ch2, n2, _)) = fence(stripped) {
                        if ch2 == ch && n2 >= n && stripped.trim_end() == stripped.trim() {
                            self.i += 1;
                            closed = true;
                            break;
                        }
                    }
                    let keep = if l.indent > min_indent {
                        &l.raw[min_indent..]
                    } else {
                        l.content
                    };
                    body.push(keep.to_string());
                    self.i += 1;
                }
                if !closed {
                    // unclosed fence consumes to end
                }
                let mut text = body.join("\n");
                if closed {
                    text.push('\n');
                }
                let _ = start;
                out.push(Block::CodeBlock { info, text, fenced: true });
                continue;
            }
            // indented code (only when not in a paragraph continuation)
            if line.indent >= 4 {
                let mut body: Vec<String> = Vec::new();
                while let Some(l) = self.cur() {
                    if l.blank {
                        // look ahead: if the next non-blank line is indented enough, continue
                        let mut k = self.i;
                        let mut all_blanks = true;
                        while let Some(n) = self.lines.get(k) {
                            if n.blank {
                                k += 1;
                            } else {
                                all_blanks = false;
                                break;
                            }
                        }
                        if all_blanks || self.lines.get(k).map(|n| n.indent < min_indent.max(4)).unwrap_or(true) {
                            break;
                        }
                        for _ in self.i..k {
                            body.push(String::new());
                        }
                        self.i = k;
                        continue;
                    }
                    if l.indent < min_indent.max(4) {
                        break;
                    }
                    let keep = if l.indent > min_indent {
                        &l.raw[min_indent..]
                    } else {
                        l.content
                    };
                    body.push(keep.to_string());
                    self.i += 1;
                }
                let mut text = body.join("\n");
                text.push('\n');
                out.push(Block::CodeBlock { info: String::new(), text, fenced: false });
                continue;
            }
            // blockquote
            if c.starts_with('>') {
                let mut inner: Vec<String> = Vec::new();
                while let Some(l) = self.cur() {
                    let lc = l.content;
                    if l.blank {
                        // lazy continuation? only if next line is a paragraph continuation
                        let nxt = self.at(1);
                        match nxt {
                            Some(n) if !n.blank && n.indent < 4 && !self.starts_block(n) => {
                                inner.push(String::new());
                                self.i += 1;
                            }
                            _ => break,
                        }
                        continue;
                    }
                    if lc.starts_with('>') {
                        let after = &lc[1..];
                        let after = after.strip_prefix(' ').unwrap_or(after);
                        inner.push(after.to_string());
                        self.i += 1;
                    } else if l.indent < 4 && !self.starts_block(l) {
                        inner.push(lc.to_string());
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                let sub = parse(&inner.join("\n"));
                for (l, b) in sub.foot_order.iter().enumerate() {
                    let _ = (l, b);
                }
                out.push(Block::BlockQuote(sub.blocks));
                self.merge_footnotes(sub);
                self.link_refs.map.extend(sub.link_refs.map);
                continue;
            }
            // list
            if let Some((ordered, num, mlen, _)) = list_marker(c) {
                if let Some(b) = self.parse_list(ordered, num, mlen, line.indent) {
                    out.push(b);
                    continue;
                }
            }
            // definition list
            if c.starts_with(':') && c[1..].starts_with(' ') {
                if let Some(b) = self.parse_deflist(min_indent) {
                    out.push(b);
                    continue;
                }
            }
            // html block
            if c.starts_with('<') {
                if let Some(b) = self.parse_html_block(min_indent) {
                    out.push(b);
                    continue;
                }
            }
            // table?
            if self.is_table_start() {
                if let Some(b) = self.parse_table() {
                    out.push(b);
                    continue;
                }
            }
            // footnote definition
            if let Some(rest) = c.strip_prefix("[^") {
                if let Some(close) = rest.find("]:") {
                    let label = &rest[..close];
                    if !label.is_empty() && !label.contains('[') {
                        let after = rest[close + 2..].trim_start();
                        let mut body: Vec<String> = vec![after.to_string()];
                        self.i += 1;
                        while let Some(l) = self.cur() {
                            if l.blank {
                                break;
                            }
                            if l.indent >= 4 {
                                body.push(l.content.to_string());
                                self.i += 1;
                            } else if !self.starts_block(l) {
                                body.push(l.content.to_string());
                                self.i += 1;
                            } else {
                                break;
                            }
                        }
                        let idx = self.foot_index(label);
                        let sub = parse(&body.join("\n"));
                        self.footnotes.push((idx, sub.blocks));
                        continue;
                    }
                }
            }
            // link reference definition
            if let Some(b) = self.try_link_ref(c) {
                if b {
                    continue;
                }
            }
            // paragraph
            let mut text: Vec<String> = Vec::new();
            let mut first = true;
            while let Some(l) = self.cur() {
                if l.blank {
                    break;
                }
                if l.indent < min_indent {
                    break;
                }
                if !first && l.indent >= 4 {
                    break;
                }
                let cc = l.content;
                if !first {
                    if is_thematic_break(cc)
                        || atx_heading(cc).is_some()
                        || fence(cc).is_some()
                        || cc.starts_with('>')
                        || list_marker(cc).is_some()
                        || self.is_table_start()
                    {
                        break;
                    }
                    if cc.starts_with("[^") && cc.contains("]:") {
                        break;
                    }
                } else {
                    // setext check
                }
                text.push(cc.to_string());
                self.i += 1;
                first = false;
            }
            if text.is_empty() {
                self.i += 1;
                continue;
            }
            // setext heading
            let is_setext = match self.cur() {
                Some(l) if !l.blank && l.indent < min_indent + 4 => {
                    let t = l.content.trim();
                    let ch0 = t.chars().next().unwrap_or(' ');
                    (ch0 == '=' || ch0 == '-')
                        && t.chars().all(|x| x == ch0)
                        && t.chars().count() >= 1
                        && text.len() == 1
                }
                _ => false,
            };
            if is_setext {
                let lvl = if self.cur().unwrap().content.trim().starts_with('=') {
                    1
                } else {
                    2
                };
                self.i += 1;
                let joined = text.join("\n");
                out.push(Block::Heading(
                    lvl,
                    parse_inlines(&joined, &self.link_refs),
                ));
                continue;
            }
            let joined = text.join("\n");
            out.push(Block::Paragraph(parse_inlines(&joined, &self.link_refs)));
        }
        out
    }

    fn merge_footnotes(&mut self, sub: Parsed) {
        for (idx, blocks) in sub.footnotes {
            self.footnotes.push((idx, blocks));
        }
        for lbl in sub.foot_order {
            if !self.foot_order.contains(&lbl) {
                self.foot_order.push(lbl);
            }
        }
    }

    fn foot_index(&mut self, label: &str) -> usize {
        match self.foot_order.iter().position(|x| x == label) {
            Some(i) => i + 1,
            None => {
                self.foot_order.push(label.to_string());
                self.foot_order.len()
            }
        }
    }

    fn starts_block(&self, l: &Line) -> bool {
        let c = l.content;
        is_thematic_break(c)
            || atx_heading(c).is_some()
            || fence(c).is_some()
            || c.starts_with('>')
            || list_marker(c).is_some()
            || c.starts_with('<')
            || c.starts_with(": ")
    }

    fn try_link_ref(&mut self, c: &str) -> Option<bool> {
        // [label]: dest ("title")
        if !c.starts_with('[') {
            return None;
        }
        let close = c.find("]:")?;
        let label = &c[1..close];
        if label.is_empty() || label.contains('[') {
            return None;
        }
        let rest = c[close + 2..].trim_start();
        if rest.is_empty() {
            return None;
        }
        let (dest, title) = split_dest_title(rest);
        if dest.is_empty() {
            return None;
        }
        self.link_refs
            .map
            .insert(label.to_string(), (dest.to_string(), title));
        self.i += 1;
        Some(true)
    }

    fn parse_list(
        &mut self,
        ordered: bool,
        num: u32,
        mlen: usize,
        indent: usize,
    ) -> Option<Block> {
        let mut items: Vec<Vec<Block>> = Vec::new();
        let mut tasks: Vec<Option<bool>> = Vec::new();
        let mut tight = true;
        let mut last_end_line: Option<usize> = None;
        let mut start = num;
        let mut first = true;
        loop {
            let line = match self.cur() {
                Some(l) => l,
                None => break,
            };
            if line.blank {
                // blank line: may be inside a loose item
                // look ahead
                let mut k = self.i;
                let mut blank_count = 0;
                while let Some(n) = self.lines.get(k) {
                    if n.blank {
                        k += 1;
                        blank_count += 1;
                    } else {
                        break;
                    }
                }
                let nxt = self.lines.get(k);
                let cont = match nxt {
                    Some(n) => {
                        if n.indent > indent
                            || (n.indent == indent && list_marker(n.content).is_some())
                        {
                            true
                        } else {
                            false
                        }
                    }
                    None => false,
                };
                if cont {
                    for _ in 0..blank_count {
                        items.last_mut().map(|v| v.push(Block::Empty));
                        self.i += 1;
                    }
                    tight = false;
                    continue;
                }
                break;
            }
            let is_marker = line.indent == indent && {
                match list_marker(line.content) {
                    Some((o2, _, _, _)) => o2 == ordered,
                    None => false,
                }
            };
            if is_marker {
                let (_, n2, ml, _) = list_marker(line.content).unwrap();
                if !first {
                    if let Some(le) = last_end_line {
                        if self.i > le + 1 {
                            tight = false;
                        }
                    }
                }
                let after = &line.content[ml..];
                let after_trim = after.trim_start();
                let after_spaces = after.len() - after_trim.len();
                let task = if !ordered {
                    task_marker(after_trim)
                } else {
                    None
                };
                if let Some((done, tlen)) = task {
                    tasks.push(Some(done));
                    let content = &after_trim[tlen..];
                    let base_indent = indent + ml + after_spaces + tlen;
                    let body = self.collect_item_body(base_indent, content, line.indent);
                    items.push(body.0);
                    if body.1 {
                        tight = false;
                    }
                    last_end_line = Some(body.2);
                    self.i = body.3;
                    first = false;
                    continue;
                }
                tasks.push(None);
                let content = after_trim.to_string();
                let base_indent = indent + ml + after_spaces;
                let body = self.collect_item_body(base_indent, &content, line.indent);
                items.push(body.0);
                if body.1 {
                    tight = false;
                }
                last_end_line = Some(body.2);
                self.i = body.3;
                first = false;
                continue;
            }
            // continuation of the last item
            if line.indent > indent {
                let base = line.indent;
                let body = self.collect_item_body(base, line.content, line.indent);
                items.last_mut()?.extend(body.0);
                if body.1 {
                    tight = false;
                }
                self.i = body.3;
                continue;
            }
            break;
        }
        if items.is_empty() {
            return None;
        }
        // remove trailing Empty blocks
        for it in items.iter_mut() {
            while matches!(it.last(), Some(Block::Empty)) {
                it.pop();
            }
        }
        Some(Block::List(ListData {
            ordered,
            start,
            tight,
            items,
            tasks,
        }))
    }

    fn collect_item_body(
        &mut self,
        min_indent: usize,
        first_line: &str,
        _line_indent: usize,
    ) -> (Vec<Block>, bool, usize, usize) {
        let start = self.i;
        // consume the first line
        let mut lines: Vec<String> = vec![first_line.to_string()];
        let first_raw_indent = self
            .lines
            .get(self.i)
            .map(|l| l.indent)
            .unwrap_or(0);
        self.i += 1;
        let mut loose = false;
        while let Some(l) = self.cur() {
            if l.blank {
                // check if the following content continues the item
                let mut k = self.i;
                let mut blanks = 0;
                while let Some(n) = self.lines.get(k) {
                    if n.blank {
                        k += 1;
                        blanks += 1;
                    } else {
                        break;
                    }
                }
                match self.lines.get(k) {
                    Some(n) if n.indent >= min_indent => {
                        for _ in 0..blanks {
                            lines.push(String::new());
                        }
                        loose = true;
                        self.i = k;
                        continue;
                    }
                    _ => break,
                }
            }
            if l.indent < min_indent {
                break;
            }
            lines.push(&l.raw[l.indent.min(l.raw.len())..]);
            self.i += 1;
        }
        let _ = first_raw_indent;
        let text = lines.join("\n");
        let sub = parse(&text);
        self.merge_footnotes(sub);
        self.link_refs.map.extend(sub.link_refs.map);
        let is_loose = loose || sub.blocks.len() > 1;
        (sub.blocks, is_loose, self.i, self.i)
    }

    fn parse_deflist(&mut self, min_indent: usize) -> Option<Block> {
        let mut entries: Vec<DefEntry> = Vec::new();
        // the previous block may be a paragraph -> becomes the term
        let mut term: Option<Vec<Inline>> = None;
        if let Some(Block::Paragraph(p)) = self.blocks.pop() {
            term = Some(p);
        }
        loop {
            let line = match self.cur() {
                Some(l) => l,
                None => break,
            };
            if line.blank {
                break;
            }
            if line.indent < min_indent {
                break;
            }
            let c = line.content;
            if let Some(rest) = c.strip_prefix(':') {
                if rest.starts_with(' ') || rest.is_empty() {
                    let mut def: Vec<String> = vec![rest.trim_start().to_string()];
                    self.i += 1;
                    while let Some(l) = self.cur() {
                        if l.blank {
                            break;
                        }
                        if l.indent < min_indent {
                            break;
                        }
                        let lc = l.content;
                        if lc.starts_with(':') && (lc[1..].starts_with(' ') || lc.len() == 1) {
                            break;
                        }
                        if self.starts_block(l) {
                            break;
                        }
                        def.push(lc.to_string());
                        self.i += 1;
                    }
                    entries.push(DefEntry {
                        term: None,
                        definition: vec![parse_inlines(&def.join("\n"), &self.link_refs)],
                    });
                    continue;
                }
            }
            // a new term line
            let mut t: Vec<String> = vec![c.to_string()];
            self.i += 1;
            while let Some(l) = self.cur() {
                if l.blank {
                    break;
                }
                let lc = l.content;
                if lc.starts_with(':') && (lc[1..].starts_with(' ') || lc.len() == 1) {
                    break;
                }
                if self.starts_block(l) {
                    break;
                }
                t.push(lc.to_string());
                self.i += 1;
            }
            term = Some(parse_inlines(&t.join("\n"), &self.link_refs));
        }
        if entries.is_empty() {
            if let Some(t) = term {
                self.blocks.push(Block::Paragraph(t));
            }
            return None;
        }
        if let Some(t) = term {
            entries[0].term = Some(t);
        }
        Some(Block::DefinitionList(entries))
    }

    fn parse_html_block(&mut self, min_indent: usize) -> Option<Block> {
        let start = self.i;
        let mut raw: Vec<String> = Vec::new();
        let mut end_cond: u8 = 0;
        {
            let c = self.cur().unwrap().content;
            end_cond = html_block_type(c);
        }
        if end_cond == 0 {
            return None;
        }
        while let Some(l) = self.cur() {
            if l.indent < min_indent && l.indent < 4 {
                break;
            }
            let lc = l.content;
            let stop = match end_cond {
                1 => lc.contains("</script") || lc.contains("</pre") || lc.contains("</style") || lc.contains("</textarea"),
                6 => lc.starts_with('<') || l.blank,
                7 => l.blank,
                _ => l.blank,
            };
            if stop {
                if end_cond == 6 && !lc.starts_with('<') {
                    break;
                }
                break;
            }
            raw.push(l.raw.to_string());
            self.i += 1;
        }
        if raw.is_empty() {
            self.i = start;
            return None;
        }
        Some(Block::HtmlBlock(raw.join("\n")))
    }

    fn is_table_start(&self) -> bool {
        let line = match self.cur() {
            Some(l) => l,
            None => return false,
        };
        if line.blank || line.indent >= 4 {
            return false;
        }
        if !line.content.contains('|') {
            return false;
        }
        match self.at(1) {
            Some(n) => is_table_delim(n.content),
            None => false,
        }
    }

    fn parse_table(&mut self) -> Option<Block> {
        let head_line = self.cur().unwrap().content.to_string();
        let head_cells = split_table_row(&head_line);
        let delim = self.at(1).unwrap().content.to_string();
        let aligns = table_aligns(&delim, head_cells.len());
        self.i += 2;
        let mut rows = Vec::new();
        while let Some(l) = self.cur() {
            if l.blank || l.indent >= 4 {
                break;
            }
            let c = l.content;
            if !c.contains('|') {
                break;
            }
            if is_table_delim(c) {
                break;
            }
            rows.push(split_table_row(c).iter().map(|s| parse_inlines(s, &self.link_refs)).collect());
            self.i += 1;
        }
        Some(Block::Table(TableData { aligns, head: head_cells.iter().map(|s| parse_inlines(s, &self.link_refs)).collect(), rows }))
    }
}

fn html_block_type(c: &str) -> u8 {
    let t = c.trim_start();
    let lower = t.to_ascii_lowercase();
    if lower.starts_with("<script")
        || lower.starts_with("<pre")
        || lower.starts_with("<style")
        || lower.starts_with("<textarea")
    {
        return 1;
    }
    if lower.starts_with("<!--") {
        return 2;
    }
    if lower.starts_with("<?") || lower.starts_with("<!") {
        return 2;
    }
    if lower.starts_with("<![CDATA[") {
        return 2;
    }
    if lower.starts_with('/') {
        let tag: String = lower[1..].chars().take_while(|x| x.is_ascii_alphanumeric()).collect();
        if !tag.is_empty() {
            return 4;
        }
    }
    if lower.starts_with('<') {
        let inner = &lower[1..];
        let name: String = inner.chars().take_while(|x| x.is_ascii_alphanumeric() || *x == '-').collect();
        if !name.is_empty() {
            return 6;
        }
    }
    0
}

pub fn split_dest_title(rest: &str) -> (String, Option<String>) {
    let r = rest.trim_start();
    if let Some(close) = r.find(')') {
        let dest = r[..close].trim().to_string();
        let tail = r[close + 1..].trim();
        let title = if tail.is_empty() {
            None
        } else {
            let t = tail.trim_matches(|c| c == '"' || c == '\'');
            if t.is_empty() { None } else { Some(t.to_string()) }
        };
        (dest, title)
    } else {
        (r.trim().to_string(), None)
    }
}

fn is_table_delim(line: &str) -> bool {
    let t = line.trim();
    if t.is_empty() || !t.contains('-') {
        return false;
    }
    for c in t.chars() {
        if c != '-' && c != ':' && c != '|' && c != ' ' {
            return false;
        }
    }
    t.contains('-')
}

fn split_table_row(line: &str) -> Vec<String> {
    let t = line.trim();
    let t = t.strip_prefix('|').unwrap_or(t);
    let t = t.strip_suffix('|').unwrap_or(t);
    t.split('|').map(|s| s.trim().to_string()).collect()
}

fn table_aligns(delim: &str, n: usize) -> Vec<u8> {
    let cells = split_table_row(delim);
    let mut out = Vec::new();
    for i in 0..n {
        let c = cells.get(i).map(|s| s.trim()).unwrap_or("");
        let lead = c.starts_with(':');
        let tail = c.ends_with(':');
        out.push(match (lead, tail) {
            (true, true) => 3,
            (true, false) => 1,
            (false, true) => 2,
            _ => 0,
        });
    }
    out
}
