// URL transformations used for links, images, wikilinks and tags.

pub const KNOWN_EXT: &[&str] = &[
    "jpg", "jpeg", "png", "gif", "svg", "webp", "avif", "bmp", "tiff", "ico", "mp4", "mp3", "wav",
    "ogg", "flac", "mov", "mkv", "webm", "avi", "pdf", "txt", "xml", "json", "html", "tar", "gz",
    "zip", "7z", "rar", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "csv", "yml", "yaml", "toml",
];

/// Escape `&` and `'` the way the reference renderer does when building hrefs.
pub fn href_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#x27;"),
            _ => out.push(c),
        }
    }
    out
}

fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hi = (bytes[i + 1] as char).to_digit(16);
            let lo = (bytes[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (hi, lo) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf_lossy(&out).to_string()
}

fn is_unsafe_byte(b: u8) -> bool {
    if b <= 0x20 || b >= 0x7f {
        return true;
    }
    matches!(
        b,
        b'"' | b'%' | b'<' | b'>' | b'\\' | b'^' | b'`' | b'{' | b'|' | b'}' | b'[' | b']'
    )
}

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        if is_unsafe_byte(b) {
            out.push_str(&format!("%{:02X}", b));
        } else {
            out.push(b as char);
        }
    }
    out
}

pub fn slugify(s: &str) -> String {
    let esc = href_escape(s);
    let dec = percent_decode(&esc);
    let enc = percent_encode(&dec);
    let lower = enc.to_lowercase();
    let mut out = String::with_capacity(lower.len());
    for c in lower.chars() {
        if c == '%' {
            out.push('-');
        } else if c.is_ascii_alphanumeric() {
            out.push(c);
        } else {
            out.push('-');
        }
    }
    out.trim_matches('-').to_string()
}

/// Convert a markdown link destination into the site URL.
pub fn to_url(dest: &str) -> String {
    let d = dest.trim();
    if d.is_empty() {
        return String::new();
    }
    if let Some(i) = d.find(':') {
        if i > 0 {
            return d.to_string();
        }
    }
    if d.starts_with('.') {
        return d.to_string();
    }
    let esc = href_escape(d);
    let (path_raw, frag) = match esc.find('#') {
        Some(i) => (&esc[..i], Some(&esc[i + 1..])),
        None => (esc.as_str(), None),
    };
    let path_noquery = match path_raw.find('?') {
        Some(i) => &path_raw[..i],
        None => path_raw,
    };
    // normalize
    let mut comps: Vec<&str> = Vec::new();
    for c in path_noquery.split('/') {
        if c.is_empty() || c == "." {
            continue;
        }
        if c == ".." {
            comps.pop();
            continue;
        }
        comps.push(c);
    }
    let normalized = comps.join("/");
    if normalized.is_empty() {
        return match frag {
            Some(f) if !f.is_empty() => format!("#{}", slugify(f)),
            _ => String::new(),
        };
    }
    let ext = path_noquery.rsplit('.').next().unwrap_or("");
    let base = if path_noquery.ends_with(".md") {
        format!(
            "{}.html",
            slugify(path_noquery.trim_end_matches(".md"))
        )
    } else if KNOWN_EXT.contains(&ext.to_lowercase().as_str()) {
        normalized.clone()
    } else {
        format!("{}.html", slugify(&normalized))
    };
    match frag {
        Some(f) if !f.is_empty() => format!("{}#{}", base, slugify(f)),
        _ => base,
    }
}

pub fn is_url_start(s: &[u8], i: usize) -> Option<(usize, bool)> {
    // returns (prefix_len, needs_http_prefix)
    let rest = &s[i..];
    for p in ["http://", "https://", "ftp://"] {
        if rest.len() >= p.len() && rest[..p.len()].eq_ignore_ascii_case(p.as_bytes()) {
            if rest.len() > p.len() {
                return Some((p.len(), false));
            }
        }
    }
    for p in ["www.", "ftp."] {
        if rest.starts_with(p.as_bytes()) {
            return Some((p.len(), true));
        }
    }
    None
}

pub fn autolink_scan(s: &str, start: usize) -> Option<usize> {
    // scan from start for the end of the url, returning the end index
    let b = s.as_bytes();
    let mut end = start;
    while end < b.len() {
        let c = b[end];
        if c == b'<' {
            break;
        }
        if c.is_ascii_whitespace() {
            break;
        }
        end += 1;
    }
    // trim trailing delimiters
    let delims: &[u8] = b".,;:!?*_~\"'";
    while end > start {
        let c = b[end - 1];
        if delims.contains(&c) {
            end -= 1;
        } else if c == b')' {
            let opens = b[..end].iter().filter(|x| **x == b'(').count();
            let closes = b[..end].iter().filter(|x| **x == b')').count();
            if closes > opens {
                end -= 1;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    if end <= start {
        None
    } else {
        Some(end)
    }
}

pub fn valid_url_part(part: &str, needs_http: bool) -> bool {
    if needs_http {
        part.contains('.')
    } else {
        !part.is_empty()
    }
}
