                // code span
                let mut n = 0;
                while i + n < b.len() && b[i + n] == b'`' {
                    n += 1;
                }
                // find a closing run of exactly n
                let mut j = i + n;
                let mut found = None;
                while j < b.len() {
                    if b[j] == b'`' {
                        let mut m = 0;
                        while j + m < b.len() && b[j + m] == b'`' {
                            m += 1;
                        }
                        if m == n {
                            found = Some(j);
                            break;
                        }
                        j += m;
                    } else {
                        j += 1;
                    }
                }
                match found {
                    Some(j) => {
                        push_text(&mut toks, &mut textbuf);
                        let content = &s[i + n..j];
                        let content = content
                            .strip_prefix(' ')
                            .unwrap_or(content);
                        let content = content.strip_suffix(' ').unwrap_or(content);
                        let content = content.replace('\n', " ");
                        toks.push(Tok::Other(Inline::Code(content)));
                        i = j + n;
                    }
                    None => {
                        for _ in 0..n {
                            textbuf.push('`');
                        }
                        i += n;
                    }
                }
            }
            b'<' => {
                // autolink or raw html
                if let Some(tok) = parse_pointy(&s[i..]) {
                    push_text(&mut toks, &mut textbuf);
                    match tok {
                        Pointy::Link(url, text) => {
                            toks.push(Tok::Other(Inline::Autolink { url, text }))
                        }
                        Pointy::Html(h) => toks.push(Tok::Other(Inline::Html(h))),
                    }
                    i += tok_len;
                    continue;
                }
                textbuf.push('<');
                i += 1;
            }
            b'&' => {
                textbuf.push('&');
                i += 1;
            }
            b'[' => {
                if let Some((tok, len)) = parse_bracket(&s[i..], refs) {
                    push_text(&mut toks, &mut textbuf);
                    toks.push(Tok::Other(tok));
                    i += len;
                    continue;
                }
                textbuf.push('[');
                i += 1;
            }
            b'!' => {
                if i + 1 < b.len() && b[i + 1] == b'[' {
                    if let Some((tok, len)) = parse_bracket(&s[i + 1..], refs) {
                        if let Inline::Link { dest, title, children } = tok {
                            push_text(&mut toks, &mut textbuf);
                            toks.push(Tok::Other(Inline::Image {
                                dest,
                                title,
                                alt: children,
                            }));
                            i += 1 + len;
                            continue;
                        }
                    }
                }
                textbuf.push('!');
                i += 1;
            }
            b'*' | b'_' | b'~' => {
                let mut n = 0;
                while i + n < b.len() && b[i + n] == c {
                    n += 1;
                }
                let before = if i == 0 { '\0' } else { prev_char(s, i) };
                let after = if i + n >= b.len() {
                    '\0'
                } else {
                    s[i + n..].chars().next().unwrap()
                };
                let can_open = !after.is_whitespace() && after != '\0';
                let can_close = !before.is_whitespace() && before != '\0';
                let intraword = !before.is_whitespace()
                    && !after.is_whitespace()
                    && before != '\0'
                    && after != '\0';
                let allowed = if c == b'_' {
                    !intraword
                } else {
                    true
                };
                push_text(&mut toks, &mut textbuf);
                if allowed {
                    toks.push(Tok::Delim {
                        ch: c,
                        n,
                        can_open: can_open && !can_close,
                        can_close: can_close && !can_open,
                    });
                } else {
                    for _ in 0..n {
                        textbuf.push(c as char);
                    }
                }
                i += n;
            }
            _ => {
                let ch_len = s[i..].chars().next().unwrap().len_utf8();
                textbuf.push_str(&s[i..i + ch_len]);
