enum Pointy {
    Link(String, String),
    Html(String),
}

fn parse_pointy(s: &str) -> Option<Pointy> {
    let close = s.find('>')?;
    let inner = &s[1..close];
    if inner.is_empty() {
        return None;
    }
    // email
    if let Some(at) = inner.find('@') {
        if at > 0 && at + 1 < inner.len() {
            let local = &inner[..at];
            let dom = &inner[at + 1..];
            if valid_local(local) && valid_domain(dom) {
                unsafe {
                    TOK_LEN = close + 1;
                }
                return Some(Pointy::Link(format!("mailto:{}", inner), inner.to_string()));
            }
        }
    }
    if inner.contains("://") || inner.starts_with("www.") || inner.starts_with("ftp.") {
        let href = if inner.starts_with("www.") {
            format!("http://{}", inner)
        } else if inner.starts_with("ftp.") && !inner.contains("://") {
            format!("http://{}", inner)
        } else {
            inner.to_string()
        };
        unsafe {
            TOK_LEN = close + 1;
        }
        return Some(Pointy::Link(href, inner.to_string()));
    }
    // raw html tag
    let lower = inner.to_ascii_lowercase();
    let name: String = lower
        .chars()
        .take_while(|x| x.is_ascii_alphanumeric() || *x == '-')
        .collect();
    if !name.is_empty() && (lower.starts_with(&name) || lower.starts_with(&format!("/{}", name))) {
        unsafe {
            TOK_LEN = close + 1;
        }
        return Some(Pointy::Html(s[..close + 1].to_string()));
    }
    None
}
