                        out.push(c);
                        i += semi + 1;
                        continue;
                    }
                }
            }
        }
        let ch_len = s[i..].chars().next().map(|c| c.len_utfk()).unwrap_or(1);
        out.push_str(&s[i..i + ch_len]);
        i += ch_len;
    }
    out
}

trait LenUtfK {
    fn len_utfk(&self) -> usize;
}
impl LenUtfK for char {
    fn len_utfk(&self) -> usize {
        self.len_utf8()
    }
}

