fn valid_local(s: &str) -> bool {
    !s.is_empty()
        && s.chars().all(|c| c.is_ascii_alphanumeric() || "._+-".contains(c))
        && !s.starts_with('.')
}

fn valid_domain(s: &str) -> bool {
    if s.is_empty() || !s.contains('.') {
        return false;
    }
    let b: Vec<char> = s.chars().collect();
    for (i, c) in b.iter().enumerate() {
        let ok = c.is_ascii_alphanumeric()
            || "._-".contains(*c)
            || (*c == '@' && i > 0 && b[i - 1] != '.');
        if !ok {
            return false;
        }
    }
    !s.contains("..")
}

fn parse_bracket(s: &str, refs: &LinkRefs) -> Option<(Inline, usize)> {
    let b = s.as_bytes();
    if b.first() != Some(&b'[') {
        return None;
    }
    // footnote?
    if b.len() > 2 && b[1] == b'^' {
        if let Some(close) = s[1..].find(']') {
            let label = &s[2..1 + close];
            if !label.is_empty() && !label.contains('[') && !label.contains(' ') {
                return Some((Inline::FootnoteRef(0), close + 2));
            }
        }
    }
    let mut close = None;
    let mut depth = 0;
    let mut j = 0;
    while j < b.len() {
        match b[j] {
            b'\\' => {
                j += 2;
                continue;
            }
            b'[' => depth += 1,
            b']' => {
                depth -= 1;
                if depth == 0 {
                    close = Some(j);
                    break;
                }
            }
            _ => {}
        }
        j += 1;
    }
    let close = close?;
    let label = &s[1..close];
    let rest = &s[close + 1..];
    if rest.starts_with('(') {
        // inline destination
        let (dest, title, consumed) = parse_inline_dest(rest)?;
        let children = parse_inlines(label, refs);
        return Some((
            Inline::Link { dest, title, children },
            close + 1 + consumed,
        ));
    }
    if rest.starts_with('[') {
        // reference
        let end = rest.find(']')?;
        let rlabel = &rest[1..end];
        let key = if rlabel.is_empty() { label } else { rlabel };
        if let Some((dest, title)) = refs.map.get(key) {
            let children = parse_inlines(label, refs);
            return Some((
                Inline::Link {
                    dest: dest.clone(),
                    title: title.clone(),
                    children,
                },
                close + 1 + end + 1,
            ));
        }
        return None;
    }
    // shortcut reference
    if let Some((dest, title)) = refs.map.get(label) {
        let children = parse_inlines(label, refs);
        return Some((
            Inline::Link {
                dest: dest.clone(),
                title: title.clone(),
                children,
            },
            close + 1,
        ));
    }
    None
}

fn parse_inline_dest(s: &str) -> Option<(String, Option<String>, usize)> {
    let b = s.as_bytes();
    if b.first() != Some(&b'(') {
        return None;
    }
    let mut i = 1;
    let mut dest = String::new();
    let mut title: Option<String> = None;
    let mut angle = false;
    if b.get(1) == Some(&b'<') {
        angle = true;
        i = 2;
        while i < b.len() && b[i] != b'>' {
            dest.push(b[i] as char);
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
        i += 1;
    } else {
        let mut depth = 0;
        while i < b.len() {
            let c = b[i];
            if c == b'\\' && i + 1 < b.len() {
                dest.push('\\');
                dest.push(b[i + 1] as char);
                i += 2;
                continue;
            }
            if c == b'(' {
                depth += 1;
            } else if c == b')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if c.is_ascii_whitespace() && depth == 0 {
                break;
            }
            dest.push(c as char);
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
    }
    // title
    let mut j = i;
    while j < b.len() && (b[j] as char).is_ascii_whitespace() {
        j += 1;
    }
    if j < b.len() && (b[j] == b'"' || b[j] == b'\'') {
        let q = b[j];
        let mut k = j + 1;
        let mut t = String::new();
        while k < b.len() && b[k] != q {
            t.push(b[k] as char);
            k += 1;
        }
        if k < b.len() {
            title = Some(t);
            i = k + 1;
        }
    } else if j < b.len() && b[j] == b'(' {
        let mut k = j + 1;
        let mut t = String::new();
        while k < b.len() && b[k] != b')' {
            t.push(b[k] as char);
            k += 1;
        }
        if k < b.len() {
            title = Some(t);
            i = k + 1;
        }
    }
    while i < b.len() && (b[i] as char).is_ascii_whitespace() {
        i += 1;
    }
    if i >= b.len() || b[i] != b')' {
        return None;
    }
    Some((dest, title, i + 1))
}

fn autolink_bare(toks: &mut Vec<Tok>) {
    let mut out: Vec<Tok> = Vec::new();
    for tok in toks.drain(..) {
        match tok {
            Tok::Str(s) => {
                let mut remaining = s.as_str();
                while !remaining.is_empty() {
                    match find_autolink(remaining) {
                        Some((start, end, url, text)) => {
                            if start > 0 {
                                out.push(Tok::Str(remaining[..start].to_string()));
                            }
                            out.push(Tok::Other(Inline::Autolink { url, text }));
                            remaining = &remaining[end..];
                        }
                        None => {
                            out.push(Tok::Str(remaining.to_string()));
                            break;
                        }
                    }
                }
            }
            other => out.push(other),
        }
    }
    *toks = out;
}

fn find_autolink(s: &str) -> Option<(usize, usize, String, String)> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        // URL
        if let Some((plen, needs_http)) = is_url_start(b, i) {
            if let Some(end) = autolink_scan(s, i) {
                let part = &s[i + plen..end];
                if valid_url_part(part, needs_http) {
                    let url = if needs_http {
                        format!("http://{}", &s[i..end])
                    } else {
                        s[i..end].to_string()
                    };
                    let text = s[i..end].to_string();
                    return Some((i, end, url, text));
                }
            }
        }
        // email
        if b[i] == b'@' && i > 0 {
            if let Some((start, end)) = email_bounds(s, i) {
                let text = s[start..end].to_string();
                return Some((start, end, format!("mailto:{}", text), text));
            }
        }
        let ch = s[i..].chars().next().unwrap();
        i += ch.len_utf8();
    }
    None
}

fn email_bounds(s: &str, at: usize) -> Option<(usize, usize)> {
    let b = s.as_bytes();
    // domain forward
    let mut j = at + 1;
    let bytes = b;
    while j < bytes.len() {
        let c = bytes[j];
        let prev = bytes[j - 1];
        let nxt = bytes.get(j + 1).copied().unwrap_or(b'\0');
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'@' {
            j += 1;
        } else if c == b'.' && nxt.is_ascii_alphanumeric() {
            j += 1;
        } else {
            break;
        }
        let _ = prev;
    }
    let dom = &s[at + 1..j];
    if !valid_domain(dom) {
        return None;
    }
    // local backward
    let mut st = at;
    while st > 0 {
        let c = bytes[st - 1];
        if c.is_ascii_alphanumeric() || "._+-".contains(c as char) {
            st -= 1;
        } else {
            break;
        }
    }
    if st == at {
        return None;
    }
    Some((st, j))
}

fn process_emphasis(toks: Vec<Tok>) -> Vec<Inline> {
    let mut out: Vec<Inline> = Vec::new();
    let mut stack: Vec<(u8, usize, usize)> = Vec::new(); // (char, tok_index, used_len)
    let mut idx = 0;
    while idx < toks.len() {
        match &toks[idx] {
            Tok::Str(s) => out.push(Inline::Text(s.clone())),
            Tok::Other(i) => out.push(i.clone()),
            Tok::Delim { ch, n, can_open, can_close } => {
                let ch = *ch;
                let n = *n;
                let can_open = *can_open;
                let can_close = *can_close;
                if can_close {
                    // find opener
                    let mut matched = None;
                    for k in (0..stack.len()).rev() {
                        if stack[k].0 == ch {
                            matched = Some(k);
                            break;
                        }
                    }
                    if let Some(k) = matched {
                        let (_, oidx, olen) = stack[k];
                        let use_len = n.min(olen);
                        let tag_is_uline = ch == b'_' && use_len >= 2;
                        // gather content between oidx and idx
                        let mut content: Vec<Inline> = out.split_off(olen_index(&toks, oidx, out.len()));
                        let _ = &mut content;
                        let inner = content;
                        let node = if tag_is_uline {
                            Inline::Uline(inner)
                        } else if use_len >= 2 {
                            Inline::Strong(inner)
                        } else {
                            Inline::Emph(inner)
                        };
                        out.push(node);
                        stack.truncate(k);
                        if n > use_len {
                            stack.push((ch, idx, n - use_len));
                        }
                        if olen > use_len {
                            stack.push((ch, oidx, olen - use_len));
                        }
                        idx += 1;
                        continue;
                    }
                }
                if can_open {
                    stack.push((ch, idx, n));
                } else {
                    for _ in 0..n {
                        out.push(Inline::Text((ch as char).to_string()));
                    }
                }
                idx += 1;
            }
        }
    }
    for (_, _, n) in stack.iter() {
        for _ in 0..*n {
            // leftover delimiters
        }
    }
    out
}

fn olen_index(_toks: &[Tok], _oidx: usize, fallback: usize) -> usize {
    fallback
}
