                        let content = content.strip_prefix(' ').unwrap_or(content);
                        let content = content.strip_suffix(' ').unwrap_or(content);
                        let content = content.replace('\n', " ");
                        toks.push(Tok::Other(Inline::Code(content)));
                        i = j + n;
                    }
                    None => {
                        for _ in 0..n {
                            textbuf.push('`');
                        }
                        i += n;
                    }
                }
            }
            b'<' => {
                if let Some((tok, len)) = parse_pointy(&s[i..]) {
                    flush!(toks, textbuf);
                    match tok {
                        Pointy::Link(url, text) => {
                            toks.push(Tok::Other(Inline::Autolink { url, text }))
                        }
                        Pointy::Html(h) => toks.push(Tok::Other(Inline::Html(h))),
                    }
