                textbuf.push('<');
                i += 1;
            }
            b'&' => {
                textbuf.push('&');
                i += 1;
            }
            b'[' => {
                if let Some((tok, len)) = parse_bracket(&s[i..], refs) {
                    flush!(toks, textbuf);
                    toks.push(Tok::Other(tok));
                    i += len;
                    continue;
                }
                textbuf.push('[');
                i += 1;
            }
            b'!' => {
                if i + 1 < b.len() && b[i + 1] == b'[' {
                    if let Some((tok, len)) = parse_bracket(&s[i + 1..], refs) {
                        if let Inline::Link { dest, title, children } = tok {
                            flush!(toks, textbuf);
                            toks.push(Tok::Other(Inline::Image {
                                dest,
                                title,
                                alt: children,
                            }));
                            i += 1 + len;
                            continue;
                        }
                    }
                }
                textbuf.push('!');
                i += 1;
            }
