                let mut n = 0;
                while i + n < b.len() && b[i + n] == c {
                    n += 1;
                }
                let before = if i == 0 { '\0' } else { prev_char(s, i) };
                let after = if i + n >= b.len() {
                    '\0'
                } else {
                    s[i + n..].chars().next().unwrap()
                };
                let after_ws = after == '\0' || after.is_whitespace();
                let before_ws = before == '\0' || before.is_whitespace();
                let intraword = !before_ws && !after_ws;
                let allowed = if c == b'_' { !intraword } else { true };
                flush!(toks, textbuf);
                if !allowed {
                    for _ in 0..n {
                        textbuf.push(c as char);
                    }
                    i += n;
                    continue;
                }
                let can_open = !after_ws;
                let can_close = !before_ws;
                if !can_open && !can_close {
                    for _ in 0..n {
                        textbuf.push(c as char);
                    }
                    i += n;
                    continue;
                }
                toks.push(Tok::Delim {
                    ch: c,
                    n,
                    can_open,
                    can_close,
                });
                i += n;
            }
            _ => {
                let ch_len = s[i..].chars().next().unwrap().len_utf8();
                textbuf.push_str(&s[i..i + ch_len]);
                i += ch_len;
            }
        }
    }
    flush!(toks, textbuf);
    autolink_bare(&mut toks);
    toks
}

