new='''fn process_emphasis(toks: Vec<Tok>) -> Vec<Inline> {
    let mut out: Vec<Inline> = Vec::new();
    // stack entries: (char, remaining, start index in out)
    let mut stack: Vec<(u8, usize, usize)> = Vec::new();
    for t in toks {
        match t {
            Tok::Str(s) => out.push(Inline::Text(s)),
            Tok::Other(i) => out.push(i),
            Tok::Delim { ch, n, can_open, can_close } => {
                let uline = ch == b'_';
                let mut nleft = n;
                while nleft > 0 && can_close {
                    let k = match stack.iter().rposition(|(c, _, _)| *c == ch) {
                        Some(k) => k,
                        None => break,
                    };
                    let r = stack[k].1;
                    let use_len = if r >= 2 && nleft >= 2 { 2 } else { 1 };
                    let st = stack[k].2;
                    let inner: Vec<Inline> = out.drain(st..).collect();
                    let node = if uline && use_len >= 2 {
                        Inline::Uline(inner)
                    } else if use_len >= 2 {
                        Inline::Strong(inner)
                    } else {
                        Inline::Emph(inner)
                    };
                    out.push(node);
                    stack[k].1 -= use_len;
                    if stack[k].1 == 0 {
                        stack.remove(k);
                    } else {
                        // keep the remaining opener: its content start is now at st
                        stack[k].2 = st;
                    }
                    nleft -= use_len;
                    if nleft == 0 {
                        break;
                    }
                    // the closer has leftovers: they become literal text
                    break;
                }
                if nleft > 0 {
                    for _ in 0..nleft {
                        out.push(Inline::Text((ch as char).to_string()));
                    }
