new=r'''const KNOWN_TAGS: &[&str] = &[
    "address","article","aside","base","basefont","blockquote","body","caption","center","col",
    "colgroup","dd","details","dialog","dir","div","dl","dt","fieldset","figcaption","figure",
    "footer","form","frame","frameset","h1","h2","h3","h4","h5","h6","head","header","hr","html",
    "iframe","legend","li","link","main","menu","menuitem","nav","noframes","ol","optgroup",
    "option","p","param","section","source","summary","table","tbody","td","tfoot","th","thead",
    "title","tr","track","ul",
];

fn tag_matches(lower: &str, tag: &str) -> bool {
    let pre = format!("<{}", tag);
    if !lower.starts_with(&pre) {
        return false;
    }
    let rest = &lower[pre.len()..];
    rest.is_empty()
        || rest.starts_with(' ')
        || rest.starts_with('\\t')
        || rest.starts_with('>')
        || rest.starts_with('\\n')
}

fn complete_open_tag(c: &str) -> Option<String> {
    // a complete open tag: <tag ...>
    if !c.starts_with('<') {
        return None;
    }
    let b: Vec<char> = c.chars().collect();
    if b.len() < 2 {
        return None;
    }
    if !(b[1].is_ascii_alphabetic()) {
        return None;
    }
    let mut i = 1;
    let mut name = String::new();
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == '-') {
        name.push(b[i]);
        i += 1;
    }
    if name.is_empty() {
        return None;
    }
    // scan for '>' allowing quoted attribute values
    let mut quote: Option<char> = None;
    while i < b.len() {
        let ch = b[i];
        if let Some(q) = quote {
            if ch == q {
                quote = None;
            }
        } else if ch == '"' || ch == '\\'' {
            quote = Some(ch);
        } else if ch == '>' {
            return Some(name);
        }
        i += 1;
    }
    None
}

fn closing_tag(c: &str) -> Option<String> {
    let t = c.trim_end();
    if !t.starts_with("</") {
        return None;
    }
    let b: Vec<char> = t.chars().collect();
    let mut i = 2;
    let mut name = String::new();
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == '-') {
        name.push(b[i]);
        i += 1;
    }
    if name.is_empty() {
        return None;
    }
    while i < b.len() && (b[i] == ' ' || b[i] == '\\t') {
        i += 1;
    }
    if i < b.len() && b[i] == '>' {
        Some(name)
    } else {
        None
    }
}

fn html_block_type(c: &str) -> u8 {
    let t = c;
    let lower = t.to_ascii_lowercase();
    for tag in ["script", "pre", "style", "textarea"] {
        if tag_matches(&lower, tag) {
            return 1;
        }
    }
    if lower.starts_with("<!--") {
        return 2;
    }
    if lower.starts_with("<![CDATA[") {
        return 5;
    }
    if lower.starts_with("<?") {
        return 3;
    }
    if lower.starts_with("<!") && lower[2..].chars().next().map(|x| x.is_ascii_alphabetic()).unwrap_or(false) {
        return 4;
    }
    // type 6: open tag with a known name, or closing tag with a known name
    if lower.starts_with("</") {
        if let Some(name) = closing_tag(&lower) {
            if KNOWN_TAGS.contains(&name.as_str()) {
                return 6;
            }
        }
    } else if let Some(name) = complete_open_tag(&lower) {
        if KNOWN_TAGS.contains(&name.to_ascii_lowercase().as_str()) {
            return 6;
        }
    }
    // type 7: complete open tag or closing tag on a line by itself
    let trimmed = t.trim_end();
    if let Some(name) = complete_open_tag(trimmed) {
        if trimmed[complete_tag_len(trimmed, &name)..].trim().is_empty() {
            return 7;
        }
    }
    if closing_tag(trimmed).is_some() && trimmed.trim().ends_with('>') {
        return 7;
    }
    0
}

fn complete_tag_len(c: &str, _name: &str) -> usize {
    // length of the complete open tag at the start of c
    let b: Vec<char> = c.chars().collect();
    let mut i = 1;
    let mut quote: Option<char> = None;
    while i < b.len() {
        let ch = b[i];
        if let Some(q) = quote {
            if ch == q {
                quote = None;
            }
        } else if ch == '"' || ch == '\\'' {
            quote = Some(ch);
        } else if ch == '>' {
            return c.char_indices().nth(i + 1).map(|(x, _)| x).unwrap_or(i + 1);
        }
        i += 1;
    }
    0
}

