/// Rewrite `href="..."` attributes in rendered HTML the way the reference does.
pub fn rewrite_hrefs(html: &str) -> String {
    let mut out = String::with_capacity(html.len());
    let b = html.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if html[i..].starts_with("href=\"") {
            let start = i + 6;
            if let Some(end) = html[start..].find('"') {
                let dest = &html[start..start + end];
                out.push_str("href=\"");
                out.push_str(&to_url(dest));
                out.push('"');
                i = start + end + 1;
                continue;
            }
        }
        let ch = html[i..].chars().next().unwrap();
        out.push_str(&html[i..i + ch.len_utf8()]);
        i += ch.len_utf8();
    }
    out
}
