    Continue,
    Break,
    FilterBlock { name: String, args: Vec<(String, Option<Expr>)>, body: Vec<Node> },
    Raw(String),
    Comment,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Val(Value),
    Var(String),
    Attr(Box<Expr>, String),
    Index(Box<Expr>, Box<Expr>),
    Call { name: String, args: Vec<(Option<String>, Expr)> },
