// ---------------------------------------------------------------------------
// Lexer / parser
// ---------------------------------------------------------------------------

struct Lexer<'a> {
    src: &'a str,
    pos: usize,
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Text(String),
    VarStart(usize, usize), // (trim_before, trim_after)
    BlockStart(usize, usize),
    VarEnd,
    BlockEnd,
    Ident(String),
    Str(String),
    Num(String),
    Op(String),
    EOF,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Lexer { src, pos: 0 }
    }
    fn next_token(&mut self) -> Tok {
        if self.pos >= self.src.len() {
            return Tok::EOF;
        }
        let rest = &self.src[self.pos..];
        if rest.starts_with("{{") || rest.starts_with("{%") || rest.starts_with("{#") {
            let kind = &rest[..2];
            let mut p = 2;
            let mut trim_before = 0;
            if rest[2..].starts_with('-') {
                trim_before = 1;
                p = 3;
            }
            self.pos += p;
            if kind == "{#" {
                // comment: find #}
                if let Some(i) = self.src[self.pos..].find("#}") {
                    let mut end = self.pos + i;
                    let mut trim_after = 0;
                    if self.src[self.pos..end].ends_with('-') {
                        trim_after = 1;
                        end -= 1;
                    }
                    self.pos = self.pos + i + 2;
                    if trim_after == 1 {
                        self.trim_ws();
                    }
                    return Tok::Text(String::new());
                }
                self.pos = self.src.len();
                return Tok::Text(String::new());
            }
            // read the inner tokens until %} or }}
            let mut toks: Vec<Tok> = Vec::new();
            loop {
                let r = &self.src[self.pos..];
                if r.starts_with("%}") || r.starts_with("}}") {
                    let mut trim_after = 0;
                    let mut adv = 2;
                    if self.src[self.pos + 2..].starts_with('-') {
                        trim_after = 1;
                        adv = 3;
                    }
                    self.pos += adv;
                    if trim_after == 1 {
                        self.trim_ws();
                    }
                    let t = if kind == "{{" {
                        Tok::VarEnd
                    } else {
                        Tok::BlockEnd
                    };
                    toks.push(t);
                    break;
                }
                if r.starts_with("-}") {
                    self.pos += 2;
                    let t = if kind == "{{" {
                        Tok::VarEnd
                    } else {
                        Tok::BlockEnd
                    };
                    toks.push(t);
                    break;
                }
                if self.pos >= self.src.len() {
                    break;
                }
                let t = self.lex_inner();
                toks.push(t);
            }
            let _ = trim_before;
            if kind == "{{" {
                return Tok::VarStart(trim_before, 0);
            }
            return Tok::BlockStart(trim_before, 0);
        }
        // text until the next {{
        let mut end = rest.len();
        for pat in ["{{", "{%", "{#"] {
            if let Some(i) = rest.find(pat) {
                if i < end {
                    end = i;
                }
            }
        }
        let text = rest[..end].to_string();
        self.pos += end;
        Tok::Text(text)
    }
    fn trim_ws(&mut self) {
        let b = self.src.as_bytes();
        while self.pos < b.len() && (b[self.pos] as char).is_whitespace() {
            self.pos += 1;
        }
    }
    fn trim_ws_back(&mut self) {
        let b = self.src.as_bytes();
        while self.pos > 0 && (b[self.pos - 1] as char).is_whitespace() {
            self.pos -= 1;
        }
    }
    fn lex_inner(&mut self) -> Tok {
        let b = self.src.as_bytes();
        while self.pos < b.len() && (b[self.pos] as char).is_whitespace() {
            self.pos += 1;
        }
        if self.pos >= b.len() {
            return Tok::EOF;
        }
        let c = b[self.pos] as char;
        if c == '"' || c == '\'' {
            let q = c;
            self.pos += 1;
            let mut s = String::new();
            while self.pos < b.len() {
                let ch = b[self.pos] as char;
                if ch == '\\' && self.pos + 1 < b.len() {
                    let n = b[self.pos + 1] as char;
                    s.push(match n {
                        'n' => '\n',
                        't' => '\t',
                        'r' => '\r',
                        '\\' => '\\',
                        '"' => '"',
                        '\'' => '\'',
                        _ => n,
                    });
                    self.pos += 2;
                    continue;
                }
                if ch == q {
                    self.pos += 1;
                    break;
                }
                s.push(ch);
                self.pos += 1;
            }
            return Tok::Str(s);
        }
        if c.is_ascii_digit() {
            let start = self.pos;
            while self.pos < b.len()
                && ((b[self.pos] as char).is_ascii_digit()
                    || b[self.pos] == b'.'
                    || b[self.pos] == b'_')
            {
                self.pos += 1;
            }
            return Tok::Num(self.src[start..self.pos].replace('_', ""));
        }
        if c.is_alphabetic() || c == '_' {
            let start = self.pos;
            while self.pos < b.len() {
                let ch = b[self.pos] as char;
                if ch.is_alphanumeric() || ch == '_' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            return Tok::Ident(self.src[start..self.pos].to_string());
        }
        // operators
        for op in [
            "**", "==", "!=", ">=", "<=", "//", "+", "-", "*", "/", "%", "~", "(", ")", ",", ".",
            "[", "]", ":", "|", "=", ">", "<", "!", "&&", "||", "0",
        ] {
            if rest.starts_with(op) {
                self.pos += op.len();
                return Tok::Op(op.to_string());
            }
        }
        self.pos += 1;
        Tok::Op((c as u32 as char).to_string())
    }
}

pub struct Parser {
    toks: Vec<Tok>,
    i: usize,
}

pub fn parse_template(src: &str) -> Vec<Node> {
    let mut lexer = Lexer::new(src);
    let mut toks = Vec::new();
    loop {
        let t = lexer.next_token();
        if t == Tok::EOF {
            break;
        }
        toks.push(t);
    }
    // apply whitespace trimming: -%} trims following whitespace; {%- trims preceding
    let mut p = Parser { toks, i: 0 };
    p.parse_nodes(None, "")
}
