            let kind = &rest[..2];
            let mut p = 2;
            let mut trim_before = false;
            if rest[2..].starts_with('-') { trim_before = true; p = 3; }
            let inner_start = pos + p;
            let mut ipos = inner_start;
            let inner = lex_inner(src, &mut ipos);
            let mut trim_after = false;
            if inner.last() == Some(&ITok::Op("-trim".into())) { trim_after = true; }
            pos = ipos;
            if kind == "{#" { continue; }
            // apply trimming
            if trim_before {
                if let Some(Tok::Text(t)) = toks.last_mut() { *t = t.trim_end().to_string(); }
            }
            let tok = if kind == "{{" { Tok::Var(inner) } else { Tok::Block(inner) };
            if trim_after {
                // trim the following text lazily: handled when the text token is emitted
                toks.push(tok);
                // trim next text
                if pos < b.len() {
                    let r = &src[pos..];
                    let mut end = r.len();
                    for pat in ["{{", "{%", "{#"] {
                        if let Some(i) = r.find(pat) { if i < end { end = i; } }
                    }
                    let txt = r[..end].trim_start().to_string();
                    pos += end;
                    if !txt.is_empty() { toks.push(Tok::Text(txt)); }
                }
                continue;
            }
            toks.push(tok);
            continue;
        }
        let mut end = rest.len();
        for pat in ["{{", "{%", "{#"] {
            if let Some(i) = rest.find(pat) { if i < end { end = i; } }
        }
        toks.push(Tok::Text(rest[..end].to_string()));
        pos += end;
    }
    toks
}

// ------------------------------------------------------------- Parser

pub struct P {
    toks: Vec<Tok>,
    i: usize,
}

pub fn parse_template(src: &str) -> Vec<Node> {
    let mut p = P { toks: lex(src), i: 0 };
    p.nodes(&[])
}

impl P {
    fn peek_block(&self) -> Option<Vec<ITok>> {
        match self.toks.get(self.i) {
            Some(Tok::Block(inner)) => Some(inner.clone()),
            _ => None,
        }
    }
    fn block_name(&self) -> Option<String> {
        match self.toks.get(self.i) {
            Some(Tok::Block(inner)) => match inner.first() {
                Some(ITok::Ident(s)) => Some(s.clone()),
                _ => None,
            },
            _ => None,
        }
    }
    fn next(&mut self) -> Option<Tok> {
        let t = self.toks.get(self.i).cloned();
        if t.is_some() { self.i += 1; }
        t
    }
    fn nodes(&mut self, until: &[&str]) -> Vec<Node> {
        let mut out = Vec::new();
        loop {
            let t = match self.toks.get(self.i).cloned() {
                Some(t) => t,
                None => break,
            };
            match t {
                Tok::Text(s) => { self.i += 1; if !s.is_empty() { out.push(Node::Text(s)); } }
                Tok::Var(inner) => {
                    self.i += 1;
                    let mut e = ExprParser { toks: inner, i: 0 };
                    out.push(Node::Expr(e.parse()));
                }
                Tok::Block(inner) => {
                    let name = match inner.first() {
                        Some(ITok::Ident(s)) => s.clone(),
                        _ => String::new(),
                    };
                    if !until.is_empty() && until.contains(&name.as_str()) {
                        break;
                    }
                    self.i += 1;
                    match name.as_str() {
                        "if" => {
                            let mut branches: Vec<(Option<Expr>, Vec<Node>)> = Vec::new();
                            let cond = {
                                let mut e = ExprParser { toks: inner.clone(), i: 1 };
                                e.parse()
                            };
                            let body = self.nodes(&["elif", "else", "endif"]);
                            branches.push((Some(cond), body));
                            loop {
                                let n = match self.block_name() {
                                    Some(n) => n,
                                    None => break,
                                };
                                let inner2 = self.peek_block().unwrap_or_default();
                                if n == "elif" {
                                    self.i += 1;
                                    let c = { let mut e = ExprParser { toks: inner2.clone(), i: 1 }; e.parse() };
                                    let body = self.nodes(&["elif", "else", "endif"]);
                                    branches.push((Some(c), body));
                                } else if n == "else" {
                                    self.i += 1;
                                    let body = self.nodes(&["endif"]);
                                    branches.push((None, body));
                                    if self.block_name() == Some("endif".to_string()) { self.i += 1; }
                                    break;
                                } else if n == "endif" {
                                    self.i += 1;
                                    break;
                                } else {
                                    break;
                                }
                            }
                            out.push(Node::If { branches });
                        }
                        "for" => {
                            let mut vars = Vec::new();
                            let mut k = 1;
                            while let Some(ITok::Ident(s)) = inner.get(k) {
                                vars.push(s.clone());
                                k += 1;
                                if let Some(ITok::Op(o)) = inner.get(k) {
                                    if o == "," { k += 1; }
                                }
                            }
                            // expect "in"
                            let mut k2 = k;
                            if let Some(ITok::Ident(s)) = inner.get(k2) {
                                if s == "in" { k2 += 1; }
                            }
                            // look for a filter |
                            let mut split = None;
                            for (idx, it) in inner.iter().enumerate().skip(k2) {
                                if let ITok::Op(o) = it {
                                    if o == "|" { split = Some(idx); break; }
                                }
                                if let ITok::Ident(s) = it {
                                    if s == "if" || s == "filter" { split = Some(idx); break; }
                                }
                            }
                            let iter_expr = {
                                let end = split.unwrap_or(inner.len());
                                let mut e = ExprParser { toks: inner[k2..end].to_vec(), i: 0 };
                                e.parse()
                            };
                            let filter = split.map(|sp| {
                                let mut e = ExprParser { toks: inner[sp + 1..].to_vec(), i: 0 };
                                e.parse()
                            });
                            let body = self.nodes(&["endfor", "else"]);
                            let mut else_body = Vec::new();
                            if self.block_name() == Some("else".to_string()) {
                                self.i += 1;
                                else_body = self.nodes(&["endfor"]);
                            }
                            if self.block_name() == Some("endfor".to_string()) { self.i += 1; }
                            out.push(Node::For { vars, iter: iter_expr, body, else_body, filter });
                        }
                        "set" => {
                            let name = match inner.get(1) {
                                Some(ITok::Ident(s)) => s.clone(),
                                _ => String::new(),
                            };
                            let value = { let mut e = ExprParser { toks: inner.clone(), i: 2 }; e.parse() };
                            out.push(Node::Set { name, value });
                        }
                        "include" => {
                            let mut name = String::new();
                            let mut ignore_missing = false;
                            for (idx, it) in inner.iter().enumerate() {
                                if let ITok::Str(s) = it { name = s.clone(); }
                                if let ITok::Ident(s) = it {
                                    if s == "ignore" { ignore_missing = true; }
                                }
                                let _ = idx;
                            }
                            out.push(Node::Include { name, ignore_missing });
                        }
                        "extends" => {
                            let mut name = String::new();
                            for it in inner.iter() {
                                if let ITok::Str(s) = it { name = s.clone(); }
                            }
                            out.push(Node::Extends(name));
                        }
                        "block" => {
                            let bname = match inner.get(1) {
                                Some(ITok::Ident(s)) => s.clone(),
                                _ => String::new(),
                            };
                            let body = self.nodes(&["endblock"]);
                            if self.block_name() == Some("endblock".to_string()) { self.i += 1; }
                            out.push(Node::Block { name: bname, body });
                        }
                        "macro" => {
                            let mname = match inner.get(1) {
                                Some(ITok::Ident(s)) => s.clone(),
                                _ => String::new(),
                            };
                            let mut params = Vec::new();
                            let mut k = 2;
                            loop {
                                match inner.get(k) {
                                    Some(ITok::Ident(s)) => { params.push(s.clone()); k += 1; }
                                    Some(ITok::Op(o)) if o == "," => { k += 1; }
                                    _ => break,
                                }
                            }
                            let body = self.nodes(&["endmacro"]);
                            if self.block_name() == Some("endmacro".to_string()) { self.i += 1; }
                            out.push(Node::Macro { name: mname, params, body });
                        }
                        "continue" => out.push(Node::Continue),
                        "break" => out.push(Node::Break),
                        "filter" => {
                            let body = self.nodes(&["endfilter"]);
                            if self.block_name() == Some("endfilter".to_string()) { self.i += 1; }
                            out.extend(body);
                        }
                        _ => {}
                    }
                }
            }
        }
        out
    }
}

// ------------------------------------------------------------- Expression parser

pub struct ExprParser {
    pub toks: Vec<ITok>,
    pub i: usize,
}

impl ExprParser {
    fn cur(&self) -> ITok {
        self.toks.get(self.i).cloned().unwrap_or(ITok::End)
    }
    fn is_op(&self, o: &str) -> bool {
        matches!(self.cur(), ITok::Op(x) if x == o)
    }
    fn eat(&mut self) -> ITok {
        let t = self.cur();
        self.i += 1;
        t
    }
    fn eat_op(&mut self, o: &str) -> bool {
        if self.is_op(o) { self.i += 1; true } else { false }
    }
    pub fn parse(&mut self) -> Expr {
        self.parse_or()
    }
    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        loop {
            if let ITok::Ident(s) = self.cur() {
                if s == "or" {
                    self.i += 1;
                    let right = self.parse_and();
                    left = Expr::Bin(Box::new(left), "or".into(), Box::new(right));
                    continue;
                }
            }
            break;
        }
        left
    }
    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        loop {
            if let ITok::Ident(s) = self.cur() {
                if s == "and" {
                    self.i += 1;
                    let right = self.parse_not();
                    left = Expr::Bin(Box::new(left), "and".into(), Box::new(right));
                    continue;
                }
            }
            break;
        }
        left
    }
    fn parse_not(&mut self) -> Expr {
        if let ITok::Ident(s) = self.cur() {
            if s == "not" {
                self.i += 1;
                let e = self.parse_not();
                return Expr::Un("not".into(), Box::new(e));
            }
        }
        self.parse_cmp()
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_concat();
        loop {
            let op = match self.cur() {
                ITok::Op(o) if o == "==" || o == "!=" || o == ">" || o == "<" || o == ">=" || o == "<=" => o.clone(),
                ITok::Ident(s) if s == "in" => "in".to_string(),
                ITok::Ident(s) if s == "is" => {
                    // test
                    self.i += 1;
                    let negated = if let ITok::Ident(s) = self.cur() {
                        if s == "not" { self.i += 1; true } else { false }
                    } else { false };
                    let name = match self.eat() {
                        ITok::Ident(s) => s,
                        _ => String::new(),
                    };
                    let mut args = Vec::new();
                    if self.is_op("(") {
                        self.i += 1;
                        while !self.is_op(")") {
                            let arg = self.parse_arg();
                            args.push(("".to_string(), arg));
                            if !self.eat_op(",") { break; }
                        }
                        self.eat_op(")");
                    }
                    left = Expr::Test { target: Box::new(left), name, args, negated };
                    continue;
                }
                _ => break,
            };
            self.i += 1;
            let right = self.parse_concat();
            left = Expr::Bin(Box::new(left), op, Box::new(right));
        }
        left
    }
    fn parse_concat(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            if self.is_op("~") {
                self.i += 1;
                let right = self.parse_add();
                left = Expr::Bin(Box::new(left), "~".into(), Box::new(right));
                continue;
            }
            break;
        }
        left
    }
    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            if self.is_op("+") || self.is_op("-") {
                let op = match self.eat() { ITok::Op(o) => o, _ => unreachable!() };
                let right = self.parse_mul();
                left = Expr::Bin(Box::new(left), op, Box::new(right));
                continue;
            }
            break;
        }
        left
    }
    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_unary();
        loop {
            if self.is_op("*") || self.is_op("/") || self.is_op("%") || self.is_op("//") || self.is_op("**") {
                let op = match self.eat() { ITok::Op(o) => o, _ => unreachable!() };
                let right = self.parse_unary();
                left = Expr::Bin(Box::new(left), op, Box::new(right));
                continue;
            }
            break;
        }
        left
    }
    fn parse_unary(&mut self) -> Expr {
        if self.is_op("!") || self.is_op("-") {
            let op = match self.eat() { ITok::Op(o) => o, _ => unreachable!() };
            let e = self.parse_unary();
            return Expr::Un(op, Box::new(e));
        }
        self.parse_postfix()
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            if self.is_op(".") {
                self.i += 1;
                match self.eat() {
                    ITok::Ident(name) => {
                        if name == "super" && self.is_op("(") {
                            self.i += 1;
                            self.eat_op(")");
                            e = Expr::Super;
                            continue;
                        }
                        e = Expr::Attr(Box::new(e), name);
                    }
                    ITok::Num(n) => { e = Expr::Index(Box::new(e), Box::new(Expr::Val(Value::Int(n.parse().unwrap_or(0))))); }
                    _ => break,
                }
                continue;
            }
            if self.is_op("[") {
                self.i += 1;
                let idx = self.parse();
                self.eat_op("]");
                e = Expr::Index(Box::new(e), Box::new(idx));
                continue;
            }
            if self.is_op("|") {
                self.i += 1;
                let name = match self.eat() {
                    ITok::Ident(s) => s,
                    _ => String::new(),
                };
                let args = self.parse_named_args_opt();
                e = Expr::Filter { target: Box::new(e), name, args };
                continue;
            }
            break;
        }
        e
    }
    fn parse_named_args_opt(&mut self) -> Vec<(String, Expr)> {
        let mut args = Vec::new();
        if self.is_op("(") {
            self.i += 1;
            while !self.is_op(")") && !matches!(self.cur(), ITok::End) {
                if let ITok::Ident(name) = self.cur() {
                    // look ahead for '='
                    let next = self.toks.get(self.i + 1).cloned().unwrap_or(ITok::End);
                    if let ITok::Op(o) = &next {
                        if o == "=" {
                            self.i += 2;
                            let v = self.parse();
                            args.push((name, v));
                            if !self.eat_op(",") { break; }
                            continue;
                        }
                    }
                }
                let v = self.parse();
                args.push((String::new(), v));
                if !self.eat_op(",") { break; }
            }
            self.eat_op(")");
        }
        args
    }
    fn parse_arg(&mut self) -> Expr {
        let e = self.parse();
        e
    }
    fn parse_primary(&mut self) -> Expr {
        match self.eat() {
            ITok::Str(s) => Expr::Val(Value::Str(s)),
            ITok::Num(n) => {
                if n.contains('.') {
                    Expr::Val(Value::Float(n.parse().unwrap_or(0.0)))
                } else {
                    Expr::Val(Value::Int(n.parse().unwrap_or(0)))
                }
            }
            ITok::Ident(s) => match s.as_str() {
                "true" => Expr::Val(Value::Bool(true)),
                "false" => Expr::Val(Value::Bool(false)),
                "none" | "null" => Expr::Val(Value::Null),
                _ => {
                    if self.is_op("(") {
                        self.i += 1;
                        let mut args = Vec::new();
                        while !self.is_op(")") && !matches!(self.cur(), ITok::End) {
                            let mut aname = None;
                            if let ITok::Ident(n) = self.cur() {
                                let next = self.toks.get(self.i + 1).cloned().unwrap_or(ITok::End);
                                if let ITok::Op(o) = &next {
                                    if o == "=" {
                                        aname = Some(n.clone());
                                        self.i += 2;
                                    }
                                }
                            }
                            let v = self.parse();
                            args.push((aname, v));
                            if !self.eat_op(",") { break; }
                        }
                        self.eat_op(")");
                        Expr::Call { name: s, args }
                    } else {
                        Expr::Var(s)
                    }
                }
            },
            ITok::Op(o) if o == "(" => {
                let mut items = Vec::new();
                while !self.is_op(")") && !matches!(self.cur(), ITok::End) {
                    items.push(self.parse());
                    if !self.eat_op(",") { break; }
                }
                self.eat_op(")");
                if items.len() == 1 { items.pop().unwrap() } else { Expr::Tuple(items) }
            }
            ITok::Op(o) if o == "[" => {
                let mut items = Vec::new();
                while !self.is_op("]") && !matches!(self.cur(), ITok::End) {
                    items.push(self.parse());
                    if !self.eat_op(",") { break; }
                }
                self.eat_op("]");
                Expr::List(items)
            }
            _ => Expr::Val(Value::Null),
        }
    }
}
