// ------------------------------------------------------------- Renderer

pub struct Engine<'a> {
    pub templates: HashMap<String, Vec<Node>>,
    pub funcs: HashMap<String, &'a dyn Fn(&mut Value, Vec<Value>) -> Result<Value, String>>,
    pub fns: HashMap<String, Box<dyn Fn(&[Value]) -> Value>>,
}

#[derive(Clone, Debug)]
pub struct BlockChain {
    pub parents: Vec<String>,
}

pub fn render_nodes(
    nodes: &[Node],
    ctx: &mut Value,
    eng: &Engine,
    out: &mut String,
    blocks: &mut std::collections::HashMap<String, Vec<Node>>,
    loop_ctx: &mut Vec<Value>,
) {
    for n in nodes {
        render_node(n, ctx, eng, out, blocks, loop_ctx);
    }
}

fn value_repr(v: &Value) -> String {
    match v {
        Value::Str(s) => s.clone(),
        other => other.to_display(),
    }
}

fn to_num(v: &Value) -> f64 {
    match v {
        Value::Int(i) => *i as f64,
        Value::Float(f) => *f,
        Value::Str(s) => s.parse().unwrap_or(0.0),
        Value::Bool(b) => {
            if *b {
                1.0
            } else {
                0.0
            }
        }
        _ => 0.0,
    }
}

fn truthy_val(v: &Value) -> bool {
    v.truthy()
}

fn render_node(
    n: &Node,
    ctx: &mut Value,
    eng: &Engine,
    out: &mut String,
    blocks: &mut std::collections::HashMap<String, Vec<Node>>,
    loop_ctx: &mut Vec<Value>,
) {
    match n {
        Node::Text(s) => out.push_str(s),
        Node::Expr(e) => {
            let v = eval(e, ctx, eng, loop_ctx);
            out.push_str(&value_repr(&v));
        }
        Node::If { branches } => {
            for (cond, body) in branches {
                let ok = match cond {
                    Some(c) => truthy_val(&eval(c, ctx, eng, loop_ctx)),
                    None => true,
                };
                if ok {
                    render_nodes(body, ctx, eng, out, blocks, loop_ctx);
                    break;
                }
            }
        }
        Node::For { vars, iter, body, else_body, filter } => {
            let base = eval(iter, ctx, eng, loop_ctx);
            let items: Vec<Value> = match &base {
                Value::Array(a) => a.clone(),
                Value::Object(m) => m
                    .iter()
                    .map(|(k, v)| Value::Array(vec![Value::Str(k.clone()), v.clone()]))
                    .collect(),
                Value::Null => Vec::new(),
                other => vec![other.clone()],
            };
            let mut items = items;
            if let Some(f) = filter {
                items.retain(|it| {
                    loop_ctx.push(it.clone());
                    let r = truthy_val(&eval(f, ctx, eng, loop_ctx));
                    loop_ctx.pop();
                    r
                });
            }
            if items.is_empty() {
                render_nodes(else_body, ctx, eng, out, blocks, loop_ctx);
                return;
            }
            let total = items.len();
            for (idx, item) in items.into_iter().enumerate() {
                match item {
                    Value::Array(pair) if vars.len() == 2 => {
                        if let Some(k) = pair.first().cloned() {
                            if let Value::Str(kk) = &k {
                                set_var(ctx, &vars[0], k.clone());
                                set_var(ctx, &vars[1], pair.get(1).cloned().unwrap_or(Value::Null));
                                let _ = kk;
                            }
                        }
                    }
                    v => {
                        set_var(ctx, &vars[0], v);
                    }
                }
                let mut lv = Value::Object(vec![
                    ("index".into(), Value::Int(idx as i64 + 1)),
                    ("index0".into(), Value::Int(idx as i64)),
                    ("first".into(), Value::Bool(idx == 0)),
                    ("last".into(), Value::Bool(idx + 1 == total)),
                    ("length".into(), Value::Int(total as i64)),
                ]);
                let _ = &mut lv;
