                }
            }
        }
        Node::Set { name, value } => {
            let v = eval(value, ctx, eng, loop_ctx);
            set_var(ctx, name, v);
        }
        Node::Include { name, ignore_missing } => {
            if let Some(tpl) = eng.templates.get(name) {
                render_nodes(tpl, ctx, eng, out, blocks, loop_ctx);
            } else if !*ignore_missing {
