fn set_var(ctx: &mut Value, name: &str, v: Value) {
    if let Value::Object(m) = ctx {
        if let Some(slot) = m.iter_mut().find(|(k, _)| k == name) {
            slot.1 = v;
        } else {
            m.push((name.to_string(), v));
        }
    }
}

fn get_var(ctx: &Value, name: &str) -> Value {
    ctx.get(name)
}

pub fn eval(e: &Expr, ctx: &mut Value, eng: &Engine, loop_ctx: &mut Vec<Value>) -> Value {
    match e {
        Expr::Val(v) => v.clone(),
        Expr::Var(name) => {
            for lv in loop_ctx.iter().rev() {
                if let Value::Object(m) = lv {
                    if m.iter().any(|(k, _)| k == name) {
                        return lv.get(name);
                    }
                }
            }
            get_var(ctx, name)
        }
        Expr::Attr(target, name) => {
            let t = eval(target, ctx, eng, loop_ctx);
            t.get(name)
        }
        Expr::Index(t, i) => {
            let t = eval(t, ctx, eng, loop_ctx);
            let i = eval(i, ctx, eng, loop_ctx);
            match i {
                Value::Int(n) => t.index(n.max(0) as usize),
                Value::Str(s) => t.get(&s),
                _ => Value::Null,
            }
        }
        Expr::Call { name, args } => {
            let a: Vec<Value> = args.iter().map(|(_, e)| eval(e, ctx, eng, loop_ctx)).collect();
            call_fn(name, &a, ctx, eng, loop_ctx)
        }
        Expr::Filter { target, name, args } => {
            let t = eval(target, ctx, eng, loop_ctx);
            let a: Vec<Value> = args
                .iter()
                .map(|(_, e)| eval(e, ctx, eng, loop_ctx))
                .collect();
            apply_filter(name, &t, &a, ctx, eng, loop_ctx)
        }
        Expr::Test { target, name, args, negated } => {
            let t = eval(target, ctx, eng, loop_ctx);
            let a: Vec<Value> = args
                .iter()
                .map(|(_, e)| eval(e, ctx, eng, loop_ctx))
                .collect();
            let r = apply_test(name, &t, &a);
            if *negated {
                Value::Bool(!r)
            } else {
                Value::Bool(r)
            }
        }
        Expr::Bin(l, op, r) => {
            let a = eval(l, ctx, eng, loop_ctx);
            let b = eval(r, ctx, eng, loop_ctx);
            binop(op, &a, &b)
        }
        Expr::Un(op, x) => {
            let v = eval(x, ctx, eng, loop_ctx);
            match op.as_str() {
                "not" | "!" => Value::Bool(!truthy_val(&v)),
                "-" => match v {
                    Value::Int(i) => Value::Int(-i),
                    Value::Float(f) => Value::Float(-f),
                    _ => Value::Null,
                },
                _ => Value::Null,
            }
        }
        Expr::List(items) => Value::Array(items.iter().map(|e| eval(e, ctx, eng, loop_ctx)).collect()),
