fn cmp_vals(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        _ => {
            let x = to_num(a);
            let y = to_num(b);
            x.partial_cmp(&y).unwrap_or(Ordering::Equal)
        }
    }
}

fn binop(op: &str, a: &Value, b: &Value) -> Value {
    match op {
        "==" => Value::Bool(values_equal(a, b)),
        "!=" => Value::Bool(!values_equal(a, b)),
        ">" => Value::Bool(cmp_vals(a, b) == std::cmp::Ordering::Greater),
        "<" => Value::Bool(cmp_vals(a, b) == std::cmp::Ordering::Less),
        ">=" => Value::Bool(cmp_vals(a, b) != std::cmp::Ordering::Less),
        "<=" => Value::Bool(cmp_vals(a, b) != std::cmp::Ordering::Greater),
        "and" => Value::Bool(truthy_val(a) && truthy_val(b)),
        "or" => Value::Bool(truthy_val(a) || truthy_val(b)),
        "~" => Value::Str(format!("{}{}", value_repr(a), value_repr(b))),
        "+" => match (a, b) {
            (Value::Str(x), Value::Str(y)) => Value::Str(format!("{}{}", x, y)),
            _ => num_op(a, b, |x, y| x + y),
        },
        "-" => num_op(a, b, |x, y| x - y),
        "*" => num_op(a, b, |x, y| x * y),
        "/" | "//" => num_op(a, b, |x, y| if y != 0.0 { x / y } else { 0.0 }),
        "%" => num_op(a, b, |x, y| if y != 0.0 { x % y } else { 0.0 }),
        _ => Value::Null,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Null, Value::Null) => true,
        (Value::Null, _) => false,
        (_, Value::Null) => false,
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q))
        }
        _ => {
            let x = to_num(a);
            let y = to_num(b);
            x == y
        }
    }
}

fn num_op(a: &Value, b: &Value, f: fn(f64, f64) -> f64) -> Value {
    let x = to_num(a);
    let y = to_num(b);
    let r = f(x, y);
    if matches!(a, Value::Float(_)) || matches!(b, Value::Float(_)) {
        Value::Float(r)
    } else {
        Value::Int(r as i64)
    }
}

fn call_fn(name: &str, args: &[Value], ctx: &mut Value, eng: &Engine, loop_ctx: &mut Vec<Value>) -> Value {
    let _ = loop_ctx;
    if let Some(f) = eng.fns.get(name) {
        return f(args);
    }
    match name {
        "super" => Value::Null,
        _ => {
            let _ = (args, ctx);
            Value::Null
        }
    }
}
