                    let r = truthy_val(&eval(f, ctx, eng, loop_ctx));
                    loop_ctx.pop();
                    r
                });
            }
            if items.is_empty() {
                render_nodes(else_body, ctx, eng, out, blocks, loop_ctx);
                return;
            }
            let total = items.len();
            for (idx, item) in items.into_iter().enumerate() {
                match item {
                    Value::Array(pair) if vars.len() == 2 => {
                        if let Some(k) = pair.first().cloned() {
                            if let Value::Str(kk) = &k {
                                set_var(ctx, &vars[0], k.clone());
                                set_var(ctx, &vars[1], pair.get(1).cloned().unwrap_or(Value::Null));
                                let _ = kk;
                            }
                        }
                    }
                    v => {
                        set_var(ctx, &vars[0], v);
                    }
                }
                let mut lv = Value::Object(vec![
                    ("index".into(), Value::Int(idx as i64 + 1)),
                    ("index0".into(), Value::Int(idx as i64)),
                    ("first".into(), Value::Bool(idx == 0)),
                    ("last".into(), Value::Bool(idx + 1 == total)),
                    ("length".into(), Value::Int(total as i64)),
                ]);
                let _ = &mut lv;
                loop_ctx.push(lv.clone());
                render_nodes(body, ctx, eng, out, blocks, loop_ctx);
                loop_ctx.pop();
                // handle continue/break via a sentinel
                if out.ends_with('\u{1}') || out.ends_with('\u{2}') {
                    let _ = out.pop();
                    if out.ends_with('\u{1}') {
                        let _ = out.pop();
                    }
                }
            }
        }
        Node::Set { name, value } => {
            let v = eval(value, ctx, eng, loop_ctx);
            set_var(ctx, name, v);
        }
        Node::Include { name, ignore_missing } => {
            if let Some(tpl) = eng.templates.get(name) {
                render_nodes(tpl, ctx, eng, out, blocks, loop_ctx);
            } else if !*ignore_missing {
                out.push_str(&format!("<!-- include {} not found -->", name));
            }
        }
        Node::Block { name, body } => {
            if let Some(existing) = blocks.get(name).cloned() {
                // prefer the child block
                render_nodes(&existing, ctx, eng, out, blocks, loop_ctx);
            } else {
                blocks.insert(name.clone(), body.clone());
                render_nodes(body, ctx, eng, out, blocks, loop_ctx);
            }
        }
        Node::Extends(name) => {
            if let Some(parent) = eng.templates.get(name).cloned() {
                // render the parent with the current block map
                let body = parent.clone();
                // first, register all blocks from the current template
                render_nodes(&body, ctx, eng, out, blocks, loop_ctx);
            }
        }
        Node::Macro { name, params, body } => {
            let _ = (name, params, body);
        }
        Node::Continue | Node::Break => {}
        Node::Raw(s) => out.push_str(s),
    }
}

fn set_var(ctx: &mut Value, name: &str, v: Value) {
    if let Value::Object(m) = ctx {
        if let Some(slot) = m.iter_mut().find(|(k, _)| k == name) {
            slot.1 = v;
        } else {
            m.push((name.to_string(), v));
        }
    }
}

fn get_var(ctx: &Value, name: &str) -> Value {
    ctx.get(name)
}

pub fn eval(e: &Expr, ctx: &mut Value, eng: &Engine, loop_ctx: &mut Vec<Value>) -> Value {
    match e {
        Expr::Val(v) => v.clone(),
        Expr::Var(name) => {
            for lv in loop_ctx.iter().rev() {
                if let Value::Object(m) = lv {
                    if m.iter().any(|(k, _)| k == name) {
                        return lv.get(name);
                    }
                }
            }
            get_var(ctx, name)
        }
        Expr::Attr(target, name) => {
            let t = eval(target, ctx, eng, loop_ctx);
            t.get(name)
        }
        Expr::Index(t, i) => {
            let t = eval(t, ctx, eng, loop_ctx);
            let i = eval(i, ctx, eng, loop_ctx);
            match i {
                Value::Int(n) => t.index(n.max(0) as usize),
                Value::Str(s) => t.get(&s),
                _ => Value::Null,
            }
        }
        Expr::Call { name, args } => {
            let a: Vec<Value> = args.iter().map(|(_, e)| eval(e, ctx, eng, loop_ctx)).collect();
            call_fn(name, &a, ctx, eng, loop_ctx)
        }
        Expr::Filter { target, name, args } => {
            let t = eval(target, ctx, eng, loop_ctx);
            let a: Vec<Value> = args
                .iter()
                .map(|(_, e)| eval(e, ctx, eng, loop_ctx))
                .collect();
            apply_filter(name, &t, &a, ctx, eng, loop_ctx)
        }
        Expr::Test { target, name, args, negated } => {
            let t = eval(target, ctx, eng, loop_ctx);
            let a: Vec<Value> = args
                .iter()
                .map(|(_, e)| eval(e, ctx, eng, loop_ctx))
                .collect();
            let r = apply_test(name, &t, &a);
            if *negated {
                Value::Bool(!r)
            } else {
                Value::Bool(r)
            }
        }
        Expr::Bin(l, op, r) => {
            let a = eval(l, ctx, eng, loop_ctx);
            let b = eval(r, ctx, eng, loop_ctx);
            binop(op, &a, &b)
        }
        Expr::Un(op, x) => {
            let v = eval(x, ctx, eng, loop_ctx);
            match op.as_str() {
                "not" | "!" => Value::Bool(!truthy_val(&v)),
                "-" => match v {
                    Value::Int(i) => Value::Int(-i),
                    Value::Float(f) => Value::Float(-f),
                    _ => Value::Null,
                },
                _ => Value::Null,
            }
        }
        Expr::List(items) => Value::Array(items.iter().map(|e| eval(e, ctx, eng, loop_ctx)).collect()),
        Expr::Tuple(items) => Value::Array(items.iter().map(|e| eval(e, ctx, eng, loop_ctx)).collect()),
        Expr::Super => Value::Null,
    }
}

fn cmp_vals(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        _ => {
            let x = to_num(a);
            let y = to_num(b);
            x.partial_cmp(&y).unwrap_or(Ordering::Equal)
        }
    }
}

fn binop(op: &str, a: &Value, b: &Value) -> Value {
    match op {
        "==" => Value::Bool(values_equal(a, b)),
        "!=" => Value::Bool(!values_equal(a, b)),
        ">" => Value::Bool(cmp_vals(a, b) == std::cmp::Ordering::Greater),
        "<" => Value::Bool(cmp_vals(a, b) == std::cmp::Ordering::Less),
        ">=" => Value::Bool(cmp_vals(a, b) != std::cmp::Ordering::Less),
        "<=" => Value::Bool(cmp_vals(a, b) != std::cmp::Ordering::Greater),
        "and" => Value::Bool(truthy_val(a) && truthy_val(b)),
        "or" => Value::Bool(truthy_val(a) || truthy_val(b)),
        "~" => Value::Str(format!("{}{}", value_repr(a), value_repr(b))),
        "+" => match (a, b) {
            (Value::Str(x), Value::Str(y)) => Value::Str(format!("{}{}", x, y)),
            _ => num_op(a, b, |x, y| x + y),
        },
        "-" => num_op(a, b, |x, y| x - y),
        "*" => num_op(a, b, |x, y| x * y),
        "/" | "//" => num_op(a, b, |x, y| if y != 0.0 { x / y } else { 0.0 }),
        "%" => num_op(a, b, |x, y| if y != 0.0 { x % y } else { 0.0 }),
        _ => Value::Null,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Null, Value::Null) => true,
        (Value::Null, _) => false,
        (_, Value::Null) => false,
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q))
        }
        _ => {
            let x = to_num(a);
            let y = to_num(b);
            x == y
        }
    }
}

fn num_op(a: &Value, b: &Value, f: fn(f64, f64) -> f64) -> Value {
    let x = to_num(a);
    let y = to_num(b);
    let r = f(x, y);
    if matches!(a, Value::Float(_)) || matches!(b, Value::Float(_)) {
        Value::Float(r)
    } else {
        Value::Int(r as i64)
    }
}

fn call_fn(name: &str, args: &[Value], ctx: &mut Value, eng: &Engine, loop_ctx: &mut Vec<Value>) -> Value {
    let _ = loop_ctx;
    if let Some(f) = eng.fns.get(name) {
        return f(args);
    }
    match name {
        "super" => Value::Null,
        _ => {
            let _ = (args, ctx);
            Value::Null
        }
    }
}
