fn arg(args: &[Value], name: &str, idx: usize) -> Option<Value> {
    if let Some(v) = args.get(idx) {
        return Some(v.clone());
    }
    None
}

fn arg_named(pairs: &[(String, Value)], name: &str) -> Option<Value> {
    pairs.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

pub fn strip_tags(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'<' {
            if let Some(end) = s[i..].find('>') {
                // replace script/style contents with nothing
                let tag = &s[i + 1..i + end];
                let lower = tag.to_ascii_lowercase();
                let name: String = lower
                    .trim_start_matches('/')
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric())
                    .collect();
                if name == "script" || name == "style" {
                    let close = format!("</{}", name);
                    if let Some(e) = s[i + end..].find(&close) {
                        i = i + end + e + close.len();
                        if let Some(x) = s[i..].find('>') {
                            i += x + 1;
                        }
                        continue;
                    }
                }
                i += end + 1;
                // html unescape entities after removing tags? comrak keeps them
                continue;
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}

