fn apply_test(name: &str, target: &Value, args: &[Value]) -> bool {
    match name {
        "defined" => !matches!(target, Value::Null),
        "undefined" => matches!(target, Value::Null),
        "string" => matches!(target, Value::Str(_)),
        "number" => matches!(target, Value::Int(_) | Value::Float(_)),
        "iterable" => matches!(target, Value::Array(_) | Value::Object(_)),
        "object" => matches!(target, Value::Object(_)),
        "even" => to_num(target) as i64 % 2 == 0,
        "odd" => to_num(target) as i64 % 2 != 0,
        "divisibleby" => {
            let d = args.first().map(to_num).unwrap_or(1.0);
            if d != 0.0 {
                to_num(target) as i64 % d as i64 == 0
            } else {
                false
            }
        }
        "starting_with" => {
            let p = args.first().map(|v| value_repr(v)).unwrap_or_default();
            value_repr(target).starts_with(&p)
        }
        "ending_with" => {
            let p = args.first().map(|v| value_repr(v)).unwrap_or_default();
            value_repr(target).ends_with(&p)
        }
        "containing" => match target {
            Value::Array(a) => a.iter().any(|x| values_equal(x, args.first().unwrap_or(&Value::Null))),
            Value::Str(s) => s.contains(&args.first().map(value_repr).unwrap_or_default()),
            _ => false,
        },
        "matching" => {
            let p = args.first().map(|v| value_repr(v)).unwrap_or_default();
            regex::Regex::new(&p).map(|re| re.is_match(&value_repr(target))).unwrap_or(false)
        }
        _ => false,
    }
}
