// chrono-like date parsing and formatting helpers.
use chrono::NaiveDateTime;

pub fn parse_naive(s: &str) -> Option<NaiveDateTime> {
    parse_date_string(s).ok()
}

pub enum DateErr {
    TooShort,
    OutOfRange,
    TooLong,
}

impl std::fmt::Display for DateErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            DateErr::TooShort => write!(f, "premature end of input"),
            DateErr::OutOfRange => write!(f, "input is out of range"),
            DateErr::TooLong => write!(f, "trailing input"),
        }
    }
}

/// Mirrors the reference parser: strict `YYYY-MM-DD` prefix, optional
/// single-space separated `HH:MM[:SS]`.
pub fn parse_date_string(s: &str) -> Result<chrono::NaiveDateTime, DateErr> {
    let shape_ok = s.len() >= 10
        && s.as_bytes()[0..4].iter().all(|b| b.is_ascii_digit())
        && s.as_bytes()[4] == b'-'
        && s.as_bytes()[5..7].iter().all(|b| b.is_ascii_digit())
        && s.as_bytes()[7] == b'-'
        && s.as_bytes()[8..10].iter().all(|b| b.is_ascii_digit());
    if !shape_ok {
        return Err(DateErr::TooShort);
    }
    let y: i32 = s[0..4].parse().map_err(|_| DateErr::TooShort)?;
    let mo: u32 = s[5..7].parse().map_err(|_| DateErr::TooShort)?;
    let d: u32 = s[8..10].parse().map_err(|_| DateErr::TooShort)?;
    let date = chrono::NaiveDate::from_ymd_opt(y, mo, d).ok_or(DateErr::OutOfRange)?;
    let mut time = chrono::NaiveTime::MIN;
    if let Some(rest) = s.get(10..) {
        if let Some(t) = rest.strip_prefix(' ') {
            let b = t.as_bytes();
            if b.len() >= 5
                && b[0..2].iter().all(|c| c.is_ascii_digit())
                && b[2] == b':'
                && b[3..5].iter().all(|c| c.is_ascii_digit())
            {
                let h: u32 = t[0..2].parse().map_err(|_| DateErr::TooShort)?;
                let mi: u32 = t[3..5].parse().map_err(|_| DateErr::TooShort)?;
                let mut sec = 0u32;
                if b.len() >= 8 && b[5] == b':' && b[6..8].iter().all(|c| c.is_ascii_digit()) {
