                    a.sort_by(|x, y| {
                        let kx = attr.as_ref().map(|k| x.get(k)).unwrap_or_else(|| x.clone());
                        let ky = attr.as_ref().map(|k| y.get(k)).unwrap_or_else(|| y.clone());
