                }
                _ => target.clone(),
            }
        }
        "round" => {
            let method = arg(args, "method", 1).map(|v| value_repr(&v)).unwrap_or_default();
            let n = to_num(target);
            let r = if method == "ceil" {
                n.ceil()
            } else if method == "floor" {
                n.floor()
            } else {
                n.round()
            };
            Value::Int(r as i64)
        }
