            };
            for x in args {
                match x {
                    Value::Array(a) => items.extend(a.clone()),
                    o => items.push(o.clone()),
                }
            }
            Value::Array(items)
        }
        "unique" => {
            let mut outv: Vec<Value> = Vec::new();
            if let Value::Array(a) = target {
                for x in a {
                    if !outv.iter().any(|y| values_equal(y, x)) {
                        outv.push(x.clone());
                    }
                }
            }
            Value::Array(outv)
        }
