use crate::tera::Value;

pub fn encode(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => format!("{}", f),
        Value::Str(s) => serde_json::to_string(s).unwrap_or_default(),
        Value::Array(a) => {
            let items: Vec<String> = a.iter().map(encode).collect();
            format!("[{}]", items.join(","))
        }
        Value::Object(m) => {
            let items: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{}:{}", serde_json::to_string(k).unwrap_or_default(), encode(v)))
                .collect();
            format!("{{{}}}", items.join(","))
        }
    }
}
