// Content parsing: front matter + markdown body.
use crate::config::Marmite;
use crate::markdown;
use crate::tera::Value;
use std::path::Path;

pub const TARGET: &str = "marmite::content";

#[derive(Debug, Clone, Default)]
pub struct Content {
    pub title: String,
    pub description: Option<String>,
    pub slug: String,
    pub html: String,
    pub tags: Vec<String>,
    pub date: Option<String>,
    pub extra: Option<Value>,
    pub links_to: Option<Value>,
    pub back_links: Vec<Value>,
    pub card_image: Option<String>,
    pub banner_image: Option<String>,
    pub authors: Vec<String>,
    pub stream: Option<String>,
    pub series: Option<String>,
    pub pinned: bool,
    pub toc: Option<String>,
    pub modified_time: i64,
    pub comments: Option<String>,
    pub source_path: String,
    pub path: std::path::PathBuf,
}

#[derive(Debug)]
pub enum ParseError {
    InvalidFrontMatter,
    Yaml(String),
    Date(String, String, String),
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ParseError::InvalidFrontMatter => write!(f, "Invalid front matter format"),
            ParseError::Yaml(e) => write!(f, "Failed to parse YAML: {}", e),
            ParseError::Date(v, p, e) => {
                write!(f, "ERROR: Invalid date format {} when parsing {}, {}", v, p, e)
            }
        }
    }
}

fn split_front_matter(src: &str) -> Option<(String, String)> {
    let trimmed_start = src.strip_prefix("---\n")?;
    if trimmed_start.starts_with("---\n") {
        return None;
    }
    let idx = trimmed_start.find("\n---\n")?;
    let fm = &trimmed_start[..idx];
    let rest = &trimmed_start[idx + 5..];
    Some((fm.to_string(), rest.to_string()))
}

/// Extract the title from the markdown body and remove that first line.
fn extract_title(body: &str) -> (String, String) {
    let lines: Vec<&str> = body.split('\n').collect();
    let mut idx = None;
    for (i, l) in lines.iter().enumerate() {
        if !l.trim().is_empty() {
            idx = Some(i);
            break;
        }
    }
    let i = match idx {
        Some(i) => i,
        None => return (String::new(), body.to_string()),
    };
    let line = lines[i];
    let title = if line.starts_with('#') {
        line.trim_start_matches('#').trim().to_string()
    } else {
        line.trim().to_string()
    };
    let rest = lines[i + 1..].join("\n");
    (title, rest)
}

pub struct Parsed {
    pub content: Content,
    pub markdown: String,
}

pub fn parse_file(path: &Path, src: &str, config: &Marmite) -> Result<Parsed, ParseError> {
    let modified = std::fs::metadata(path)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let (front, body) = match split_front_matter(src) {
        Some((f, b)) => (f, b),
        None => (String::new(), src.to_string()),
    };
    let mut fm: HashMap<String, crate::yaml::YamlValue> = HashMap::new();
    let _ = &mut fm;
    if !front.trim().is_empty() {
        // parse yaml into a generic map
        let v = match crate::yaml::parse_mapping(&front) {
            Ok(v) => v,
            Err(e) => return Err(ParseError::Yaml(e)),
        };
        fm = v;
    }
    let mut body_md = body.clone();
    let mut title = String::new();
    if let Some(t) = fm.get("title").and_then(|v| v.as_str()) {
        title = t.to_string();
    } else {
        let (t, rest) = extract_title(&body_md);
        title = t;
        body_md = rest;
    }
    let date = match fm.get("date") {
        Some(crate::yaml::YamlValue::Str(s)) => {
            let trimmed = s.trim().to_string();
            match crate::dates::parse_date_string(&trimmed) {
                Ok(dt) => Some(dt.format("%Y-%m-%dT%H:%M:%S").to_string()),
                Err(e) => {
                    return Err(ParseError::Date(
                        trimmed,
                        path.display().to_string(),
                        e.to_string(),
                    ))
                }
            }
        }
        _ => None,
    };
    let tags = fm.get("tags").and_then(|v| v.as_str()).map(|s| {
        s.split(',')
            .map(|x| x.trim().to_string())
            .filter(|x| !x.is_empty())
            .collect::<Vec<_>>()
    });
    let mut title_for_slug = title.clone();
    let mut c = Content {
        title: title.clone(),
        description: fm.get("description").and_then(|v| v.as_str()).map(|s| s.to_string()),
        slug: String::new(),
        html: String::new(),
        tags: tags.unwrap_or_default(),
        date,
        extra: fm.get("extra").map(crate::yaml::to_value),
        links_to: None,
        back_links: Vec::new(),
        card_image: fm.get("card_image").and_then(|v| v.as_str()).map(|s| s.to_string()),
        banner_image: fm.get("banner_image").and_then(|v| v.as_str()).map(|s| s.to_string()),
        authors: fm
            .get("authors")
            .map(crate::yaml::string_list)
            .unwrap_or_default(),
        stream: fm.get("stream").and_then(|v| v.as_str()).map(|s| s.to_string()).filter(|s| !s.is_empty()),
        series: fm.get("series").and_then(|v| v.as_str()).map(|s| s.to_string()).filter(|s| !s.is_empty()),
        pinned: fm.get("pinned").map(|v| v.truthy()).unwrap_or(false),
        toc: None,
        modified_time: modified,
        comments: fm.get("comments").and_then(|v| v.as_str()).map(|s| s.to_string()),
        source_path: path.display().to_string(),
        path: path.to_path_buf(),
    };
    if title_for_slug.is_empty() {
        // fall back to the filename
        title_for_slug = path
            .file_stem()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_default();
    }
    let base_slug = crate::links::slugify(&title_for_slug);
    c.slug = match &c.stream {
        Some(s) if !s.is_empty() => format!("{}-{}", s, base_slug),
        _ => base_slug,
    };
    Ok(Parsed { content: c, markdown: body_md })
}

