// Minimal YAML front matter handling built on serde_yaml.
use serde_yaml::Value as Y;
pub use serde_yaml::Value as YamlValue;

pub fn parse_mapping(s: &str) -> Result<std::collections::HashMap<String, YamlValue>, String> {
    let v: Y = serde_yaml::from_str(s).map_err(|e| e.to_string())?;
    match v {
        Y::Mapping(m) => {
            let mut out = std::collections::HashMap::new();
            for (k, v) in m {
                out.insert(yaml_str(&k), v);
            }
            Ok(out)
        }
        _ => Err("YAML front matter is not a valid mapping".to_string()),
    }
}

pub fn yaml_str(v: &serde_yaml::Mapping) -> String {
    match serde_yaml::to_string(v) {
        Ok(s) => s.trim().trim_matches('\'').trim_matches('"').to_string(),
        Err(_) => String::new(),
    }
}

pub fn as_str(v: &YamlValue) -> Option<String> {
    match v {
        Y::String(s) => Some(s.clone()),
        Y::Number(n) => Some(n.to_string()),
        Y::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

pub fn truthy(v: &YamlValue) -> bool {
    match v {
        Y::Bool(b) => *b,
        Y::String(s) => !s.is_empty(),
