pub fn collect_content(
    input: &Path,
    config: &Marmite,
    log: bool,
) -> Result<(Vec<crate::content::Content>, Vec<crate::content::Content>), String> {
    let base = if input.join(&config.content_path).is_dir() {
        input.join(&config.content_path)
    } else {
        input.to_path_buf()
    };
    let mut posts: Vec<crate::content::Content> = Vec::new();
    let mut pages: Vec<crate::content::Content> = Vec::new();
    let mut paths: Vec<PathBuf> = Vec::new();
    collect_md(&base, &mut paths);
    paths.sort();
    for p in paths {
        let name = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        if name.starts_with('_') || name.starts_with('.') {
            continue;
        }
        if !name.to_lowercase().ends_with(".md") {
            continue;
        }
        let src = match std::fs::read_to_string(&p) {
            Ok(s) => s,
            Err(e) => {
                crate::logger::log(1, crate::content::TARGET, &format!("Failed to read {}: {}", p.display(), e));
                continue;
            }
        };
        match crate::content::parse_file(&p, &src, config) {
            Ok(parsed) => {
                let html = crate::markdown::render_doc(&crate::markdown::parse(&parsed.markdown));
                let mut c = parsed.content;
                c.html = crate::links::rewrite_hrefs(&html);
                if c.date.is_some() {
                    posts.push(c);
                } else {
                    pages.push(c);
                }
            }
            Err(e) => {
                crate::logger::log(1, TARGET, &format!("Failed to process content: \"{}\"", e));
            }
        }
    }
    posts.sort_by(|a, b| b.date.cmp(&a.date));
    Ok((posts, pages))
}

fn collect_md(dir: &Path, out: &mut Vec<PathBuf>) {
    let rd = match std::fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return,
    };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            let name = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
            if name == "media" || name.starts_with('.') {
                continue;
            }
            collect_md(&p, out);
        } else {
            out.push(p);
        }
    }
}

/// Assemble the markdown source for a content item from the fragments.
pub fn assemble(markdown: &str, fragments: &HashMap<String, String>) -> String {
    let header = fragments.get("_markdown_header.md").cloned().unwrap_or_default();
    let footer = fragments.get("_markdown_footer.md").cloned().unwrap_or_default();
    let refs = fragments.get("_references.md").cloned().unwrap_or_default();
