impl<'a> Build<'a> {
    pub fn engine(&self) -> Engine<'static> {
        Engine {
            templates: self.templates.map.clone(),
            funcs: HashMap::new(),
            fns: HashMap::new(),
        }
    }

    pub fn site_data(&self) -> SiteData {
        SiteData {
            config: self.config.clone(),
            posts: self.posts.clone(),
            pages: self.pages.clone(),
            tag: self.tag.clone(),
            archive: self.archive.clone(),
            author: self.author.clone(),
            stream: self.stream.clone(),
            series: self.series.clone(),
            latest_timestamp: self.now.timestamp(),
            config_path: "./marmite.yaml".to_string(),
            force_render: true,
            galleries: Value::Object(vec![]),
        }
    }

    fn render(&self, tpl: &str, ctx: &Value) -> Option<String> {
        let nodes = self.templates.map.get(tpl)?.clone();
        let eng = self.engine();
        let mut out = String::new();
        let mut blocks: HashMap<String, Vec<Node>> = HashMap::new();
        let mut loop_ctx = Vec::new();
        // handle extends
        let mut nodes = nodes;
        if let Some(crate::tera::Node::Extends(name)) = nodes.first().cloned() {
            if let Some(parent) = self.templates.map.get(&name).cloned() {
                // register all blocks from the child
                register_blocks(&nodes, &mut blocks);
                nodes = parent;
            }
        }
        let mut c = ctx.clone();
        crate::tera::render_nodes(&nodes, &mut c, &eng, &mut out, &mut blocks, &mut loop_ctx);
        Some(out)
    }

    pub fn write_page(&mut self, name: &str, html: &str) {
        let path = self.output.join(name);
        write_file(&path, html);
        crate::logger::log(3, TARGET, &format!("Generated {}", path.display()));
    }

    pub fn build_content_pages(&mut self) {
        let site = self.site_data();
        let base = site.to_value();
        for c in self.posts.iter().chain(self.pages.iter()) {
            let fname = format!("{}.html", c.slug);
            let out_path = self.output.join(&fname);
            if !self.force_render() && out_path.exists() {
                if let Ok(m) = std::fs::metadata(&out_path) {
                    if let Ok(t) = m.modified() {
                        if let Ok(d) = t.duration_since(std::time::UNIX_EPOCH) {
                            if d.as_secs() as i64 >= c.modified_time {
                                crate::logger::log(3, TARGET, &format!("Generated {}", out_path.display()));
                                continue;
                            }
                        }
                    }
                }
            }
            let mut ctx = base.clone();
            if let Value::Object(m) = &mut ctx {
                let cv = crate::site::content_to_value(c);
                if let Value::Object(fields) = &cv {
                    for (k, v) in fields.clone() {
                        if k == "site" || k == "posts" || k == "pages" || k == "tag" || k == "archive"
                            || k == "author" || k == "stream" || k == "series"
                            || k == "latest_timestamp" || k == "config_path"
                            || k == "force_render" || k == "generated_urls" || k == "galleries"
                        {
                            continue;
                        }
                        m.push((k, v));
                    }
                }
                m.push(("content".to_string(), cv));
                m.push(("title".to_string(), Value::Str(c.title.clone())));
                m.push(("current_page".to_string(), Value::Str(fname.clone())));
                if let Some(f) = self.fragments.get("_announce.md") {
                    m.push(("announce".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(f) = self.fragments.get("_header.md") {
                    m.push(("header".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(f) = self.fragments.get("_footer.md") {
                    m.push(("footer".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(f) = self.fragments.get("_htmlhead.md") {
                    m.push(("htmlhead".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(f) = self.fragments.get("_htmltail.md") {
                    m.push(("htmltail".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(f) = self.fragments.get("_comments.md") {
                    m.push(("comments".to_string(), Value::Str(fragment_html(f, &self.fragments))));
                }
                if let Some(stream) = &c.stream {
                    let _ = stream;
                }
            }
            crate::logger::log(4, TARGET, &format!("x context: \"title: {},date: {},tags: {:?}\"", c.title, c.date.clone().map(|d| format!("Some({})", d)).unwrap_or("None".to_string()), c.tags));
            let html = match self.render("content.html", &ctx) {
                Some(h) => h,
                None => {
                    crate::logger::log(1, TARGET, &format!("Failed to render 'content.html'"));
                    continue;
                }
            };
            self.write_page(&fname, &html);
        }
    }

    pub fn force_render(&self) -> bool {
        self.force
    }
}

fn register_blocks(nodes: &[Node], blocks: &mut HashMap<String, Vec<Node>>) {
    for n in nodes {
        if let Node::Block { name, body } = n {
            blocks.insert(name.clone(), body.clone());
        }
    }
}
