pub fn run(
    input: &Path,
    output: &Path,
    config: &Marmite,
    force: bool,
    show_urls: bool,
) -> Result<(), String> {
    let start = std::time::Instant::now();
    crate::logger::log(4, TARGET, &format!("Site data galleries count: 0"));
    let mut b = Build {
        input: input.to_path_buf(),
        output: output.to_path_buf(),
        config,
        templates: load_templates(input, config),
        fragments: read_fragments(input, config),
        posts: vec![],
        pages: vec![],
        tag: vec![],
        stream: vec![],
        author: vec![],
        series: vec![],
        archive: vec![],
        urls: crate::site::Urls::new(),
        wikilinks: HashMap::new(),
        sitemap: vec![],
        now: chrono::Utc::now(),
        force,
    };
    let (posts, pages) = crate::site::collect_content(input, config, true)?;
    b.posts = posts;
    b.pages = pages;
    // build group maps
    let mut tagmap: HashMap<String, Vec<Content>> = HashMap::new();
    let mut streammap: HashMap<String, Vec<Content>> = HashMap::new();
    let mut authmap: HashMap<String, Vec<Content>> = HashMap::new();
