            ("links".to_string(), Value::Null),
        ]),
    }
}

pub fn copy_static(input: &Path, config: &Marmite, output: &Path, theme: bool) {
    let out_static = output.join(&config.static_path);
    if theme {
        if let Some(t) = &config.theme {
            let src = PathBuf::from(t).join("static");
            if src.is_dir() {
                crate::logger::log(3, TARGET, &format!("Copied '{}' to '{}/'", src.display(), output.display()));
                copy_dir(&src, &out_static);
            }
        }
    } else {
        std::fs::create_dir_all(&out_static).ok();
        for (name, data) in embedded::STATIC {
            let p = out_static.join(name);
            if let Some(parent) = p.parent() {
                std::fs::create_dir_all(parent).ok();
            }
            std::fs::write(&p, data).ok();
            crate::logger::log(
                3,
                "marmite::embedded",
                &format!("Generated {}", p.display()),
            );
        }
        // theme static? no
    }
    let _ = input;
}

pub fn copy_dir(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).ok();
    if let Ok(rd) = std::fs::read_dir(src) {
        for e in rd.flatten() {
            let p = e.path();
            let d = dst.join(p.file_name().unwrap_or_default());
            if p.is_dir() {
                copy_dir(&p, &d);
            } else {
                std::fs::copy(&p, &d).ok();
            }
        }
    }
}
