    pub fn render_group_pages(&mut self) {
        // group overview pages
        let mut pairs: Vec<(String, Vec<(String, Vec<Content>)>, &str, String)> = Vec::new();
        pairs.push((
            "tags.html".to_string(),
            self.tag.clone(),
            "Tag",
            config_tags_title(self.config),
        ));
        pairs.push((
            "streams.html".to_string(),
            self.stream.clone(),
