            self.config.authors_title.clone(),
        ));
        pairs.push((
            "series.html".to_string(),
            self.series.clone(),
            "Series",
            self.config.series_title.clone(),
        ));
        pairs.push((
            "archive.html".to_string(),
            self.archive.clone(),
            "Archive",
            self.config.archives_title.clone(),
        ));
        for (fname, groups, kind, title) in pairs {
            let items: Vec<Content> = Vec::new();
            let _ = items;
            let mut extra = vec![
                ("kind".to_string(), Value::Str(kind.to_string())),
                (
                    "group".to_string(),
                    Value::Array(
                        groups
                            .iter()
                            .map(|(n, items)| {
                                Value::Array(vec![
                                    Value::Str(n.clone()),
                                    Value::Array(items.iter().map(crate::site::content_to_value).collect()),
                                ])
                            })
                            .collect(),
                    ),
                ),
            ];
            let _ = &mut extra;
            self.render_group_overview(&fname, kind, &groups, &title);
        }
        // individual group pages
        let tag = self.tag.clone();
        for (name, items) in &tag {
            let slug = crate::links::slugify(name);
            let title = group_title("Tag", name, self.config);
            self.render_list(
                &format!("tag-{}.html", slug),
                &title,
                items,
                self.config.pagination,
                vec![],
            );
            self.urls.tags.push(format!("tag-{}.html", slug));
        }
        let stream = self.stream.clone();
        for (name, items) in &stream {
            let slug = crate::links::slugify(name);
            let title = group_title("Stream", name, self.config);
            self.render_list(&format!("{}.html", slug), &title, items, self.config.pagination, vec![]);
            self.urls.streams.push(format!("{}.html", slug));
        }
        let author = self.author.clone();
        for (name, items) in &author {
            let slug = crate::links::slugify(name);
            let title = name.clone();
            self.render_list(
                &format!("author-{}.html", slug),
                &title,
                items,
                self.config.pagination,
                vec![(
                    "author".to_string(),
                    author_value(name, self.config),
                )],
            );
            self.urls.authors.push(format!("author-{}.html", slug));
        }
        let series = self.series.clone();
        for (name, items) in &series {
            let slug = crate::links::slugify(name);
            let title = group_title("Series", name, self.config);
            self.render_list(
                &format!("series-{}.html", slug),
                &title,
                items,
                self.config.pagination,
                vec![],
            );
            self.urls.series.push(format!("series-{}.html", slug));
        }
        let archive = self.archive.clone();
        for (name, items) in &archive {
