    pub fn render_group_overview(
        &mut self,
        fname: &str,
        kind: &str,
        groups: &[(String, Vec<Content>)],
        title: &str,
    ) {
        let site = self.site_data();
        let mut ctx = site.to_value();
        let grouped: Vec<(String, Vec<Content>)> = groups
            .iter()
            .filter(|(n, _)| !(kind == "Stream" && n == "draft"))
            .cloned()
            .collect();
        let gm: Vec<Value> = grouped
            .iter()
            .map(|(n, items)| {
                Value::Array(vec![
                    Value::Str(n.clone()),
                    Value::Array(items.iter().map(crate::site::content_to_value).collect()),
                ])
            })
            .collect();
        if let Value::Object(m) = &mut ctx {
            m.push(("kind".to_string(), Value::Str(kind.to_string())));
            m.push(("group".to_string(), Value::Array(gm)));
            m.push(("title".to_string(), Value::Str(title.to_string())));
            m.push(("current_page".to_string(), Value::Str(fname.to_string())));
            if kind == "Tag" {
                let map: Vec<(String, Value)> = grouped
                    .iter()
                    .map(|(n, items)| {
                        (
                            crate::links::slugify(n),
                            Value::Array(items.iter().map(crate::site::content_to_value).collect()),
                        )
                    })
                    .collect();
                m.push(("tag_map".to_string(), Value::Object(map)));
            }
            for frag in ["_announce.md", "_header.md", "_footer.md", "_htmlhead.md", "_htmltail.md"] {
                if let Some(f) = self.fragments.get(frag) {
                    m.push((
                        frag.trim_start_matches('_').trim_end_matches(".md").to_string(),
                        Value::Str(fragment_html(f, &self.fragments)),
                    ));
                }
            }
        }
        let html = match self.render("group.html", &ctx) {
            Some(h) => h,
            None => {
                crate::logger::log(1, TARGET, &format!("Failed to render 'group.html'"));
                return;
            }
        };
        self.write_page(fname, &html);
    }

    pub fn render_404(&mut self) {
        let site = self.site_data();
        let mut ctx = site.to_value();
        let content = match self.fragments.get("_404.md") {
            Some(src) => {
                let html = fragment_html(src, &self.fragments);
                let mut c = Content::default();
                c.title = "Not Found".to_string();
                c.slug = "404".to_string();
                c.html = html;
                c
            }
            None => {
                let mut c = Content::default();
                c.title = "Not Found".to_string();
                c.slug = "404".to_string();
                c.html = String::new();
                c
            }
        };
        if let Value::Object(m) = &mut ctx {
            m.push(("content".to_string(), crate::site::content_to_value(&content)));
            let cv = crate::site::content_to_value(&content);
            if let Value::Object(fields) = &cv {
                for (k, v) in fields.clone() {
                    if !matches!(k.as_str(), "site"|"posts"|"pages"|"tag"|"archive"|"author"|"stream"|"series"|"latest_timestamp"|"config_path"|"force_render"|"generated_urls"|"galleries") {
                        m.push((k, v));
                    }
                }
            }
            m.push(("title".to_string(), Value::Str("Page not found".to_string())));
            m.push(("current_page".to_string(), Value::Str("404.html".to_string())));
        }
        let html = match self.render("content.html", &ctx) {
            Some(h) => h,
            None => return,
        };
        self.write_page("404.html", &html);
    }
}

fn config_tags_title(c: &Marmite) -> String {
    c.tags_title.clone()
