pub fn author_value(name: &str, config: &Marmite) -> Value {
    match config.authors.get(name) {
        Some(a) => Value::Object(vec![
            ("name".to_string(), Value::Str(a.name.clone())),
            (
                "avatar".to_string(),
                a.avatar.clone().map(Value::Str).unwrap_or(Value::Str(String::new())),
            ),
            (
                "bio".to_string(),
                a.bio.clone().map(Value::Str).unwrap_or(Value::Null),
            ),
            (
                "links".to_string(),
                a.links
                    .clone()
                    .map(|l| Value::Array(l.iter().map(|(x, y)| Value::Array(vec![Value::Str(x.clone()), Value::Str(y.clone())])).collect()))
                    .unwrap_or(Value::Null),
            ),
        ]),
        None => Value::Object(vec![
            ("name".to_string(), Value::Str(name.to_string())),
            ("avatar".to_string(), Value::Str(String::new())),
            ("bio".to_string(), Value::Null),
            ("links".to_string(), Value::Null),
        ]),
    }
}

