// Minimal built-in HTTP server.
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

pub const TARGET: &str = "marmite::server";

fn http_date() -> String {
    use chrono::Datelike;
    let now = chrono::Utc::now();
    let days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let months = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    let wd = days[now.weekday().num_days_from_sunday() as usize];
    format!(
        "{}, {:02} {} {} {:02}:{:02}:{:02} GMT",
        wd,
        now.day(),
        months[(now.month() - 1) as usize],
        now.year(),
        now.hour(),
        now.minute(),
        now.second()
    )
}

fn mime_for(path: &str) -> Option<&'static str> {
    if path.ends_with(".js") {
        Some("text/javascript")
    } else {
        None
    }
}

pub fn serve(root: &Path, bind: &str) {
    use std::net::TcpListener;
    let addr = if bind.contains(':') {
        bind.to_string()
    } else {
        format!("0.0.0.0:{}", bind)
    };
    let listener = match TcpListener::bind(&addr) {
        Ok(l) => l,
        Err(e) => {
            crate::logger::log(1, TARGET, &format!("Failed to bind {}: {}", addr, e));
            return;
        }
    };
    crate::logger::log(
        3,
        TARGET,
        &format!("Server started at http://{}/ - Type ^C to stop.", addr),
    );
    for stream in listener.incoming() {
        let mut stream = match stream {
            Ok(s) => s,
            Err(_) => continue,
        };
        let mut buf = [0u8; 4096];
        let n = match stream.read(&mut buf) {
            Ok(n) => n,
            Err(_) => continue,
        };
        let req = String::from_utf_lossy(&buf[..n]).to_string();
        let first = req.lines().next().unwrap_or_default().to_string();
        let mut parts = first.split_whitespace();
        let _method = parts.next().unwrap_or("GET");
        let path = parts.next().unwrap_or("/");
        let _version = parts.next().unwrap_or("HTTP/1.1");
        let rel = path.trim_start_matches('/');
        let rel = if rel.is_empty() { "index.html" } else { rel };
        let full: PathBuf = root.join(rel);
        let (found, data) = if full.is_file() {
            (
                true,
                std::fs::read(&full).unwrap_or_default(),
            )
        } else {
            let nf = root.join("404.html");
            if nf.is_file() {
                (false, std::fs::read(&nf).unwrap_or_default())
            } else {
                (false, Vec::new())
            }
        };
        let status = if found { 200 } else { 404 };
        crate::logger::log(
            if found { 3 } else { 1 },
            TARGET,
            &format!("\"{}\" {} -", first, status),
        );
        let mut resp = String::new();
        resp.push_str("HTTP/1.1 200 OK\r\n");
        resp.push_str("Server: tiny-http (Rust)\r\n");
        resp.push_str(&format!("Date: {}\r\n", http_date()));
        if let Some(mt) = mime_for(rel) {
            resp.push_str(&format!("Content-Type: {}\r\n", mt));
        }
        resp.push_str(&format!("Content-Length: {}\r\n\r\n", data.len()));
        let _ = stream.write_all(resp.as_bytes());
        let _ = stream.write_all(&data);
        let _ = stream.flush();
    }
}
