fn opt_str(m: &clap::ArgMatches, k: &str) -> Option<String> {
    m.get_one::<String>(k).map(|s| s.to_string())
}

fn opt_bool(m: &clap::ArgMatches, k: &str) -> Option<bool> {
    m.get_one::<String>(k).map(|s| s == "true")
}

fn init_logger(verbose: u8) {
    let level = logger::level_from_verbosity(verbose);
    match std::env::var("RUST_LOG") {
        Ok(spec) => {
            logger::set_level(logger::level_from_env(&spec, "marmite"));
        }
        Err(_) => logger::set_level(level),
    }
}

fn main() {
    let cmd = build_cli();
    let m = cmd.get_matches();
    let verbose = m.get_count("verbose") as u8;
    init_logger(verbose);
    let input = m.get_one::<String>("input_folder").cloned();
    let output = m.get_one::<String>("output_folder").cloned();
    let config_path = m.get_one::<String>("config").cloned().unwrap_or_default();
    let force = m.get_flag("force");

    // utility commands first
    if m.get_flag("init-site") {
        let inp = input.clone().unwrap_or_default();
        let dir = PathBuf::from(&inp);
        crate::theme::init_site(&dir, output.as_deref());
        return;
    }
    if let Some(title) = m.get_one::<String>("new") {
        let dir = PathBuf::from(input.clone().unwrap_or_default());
        crate::theme::new_content(
            &dir,
            title,
            opt_str(&m, "t").as_deref(),
            m.get_flag("p"),
            m.get_flag("e"),
        );
        return;
    }
    if m.get_flag("init-templates") {
        let dir = PathBuf::from(input.clone().unwrap_or_default());
        crate::theme::init_templates(&dir);
        return;
    }
    if let Some(name) = m.get_one::<String>("start-theme") {
        let dir = PathBuf::from(input.clone().unwrap_or_default());
        crate::theme::start_theme(&dir, name);
        return;
    }
    if let Some(src) = m.get_one::<String>("set-theme") {
        let dir = PathBuf::from(input.clone().unwrap_or_default());
        crate::theme::set_theme(&dir, &config_path, src);
        return;
    }
    if m.get_flag("generate-config") {
        let dir = PathBuf::from(input.clone().unwrap_or_default());
        crate::theme::generate_config(&dir, &config_path);
        return;
    }
    if m.get_flag("shortcodes") {
        crate::theme::list_shortcodes(&config_path);
        return;
    }

    let input = match input {
        Some(i) => i,
        None => return,
    };
    let input_dir = PathBuf::from(&input);
    if !input_dir.is_dir() {
        log_error!("marmite", "Input folder does not exist: {:?}", input_dir);
        std::process::exit(1);
    }
    let cfg_path = if Path::new(&config_path).is_absolute() {
        PathBuf::from(&config_path)
    } else {
        input_dir.join(&config_path)
    };
    let mut config = match crate::config::load(&cfg_path) {
        Ok(c) => {
            log_info!(
                "marmite::site",
                "Config loaded from: {}",
                if cfg_path.exists() {
                    cfg_path.display().to_string()
                } else {
                    "defaults".to_string()
                }
            );
            c
        }
        Err(e) => {
            if !cfg_path.exists() {
                log_info!(
                    "marmite::site",
                    "Unable to read '{}', assuming defaults.: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}",
                    cfg_path.display()
                );
                log_info!("marmite::site", "Config loaded from: defaults");
                crate::config::Marmite::default()
            } else {
                log_error!(
                    "marmite::site",
                    "Failed to parse config YAML: {:?}",
                    serde_yaml_error(&cfg_path)
                );
                std::process::exit(1);
            }
        }
    };
    apply_cli_overrides(&m, &mut config);
    let output_dir = match output {
        Some(o) => PathBuf::from(o),
        None => input_dir.join("site"),
    };
    match crate::build::run(&input_dir, &output_dir, &config, force, m.get_flag("show-urls")) {
        Ok(_) => {
            if m.get_flag("serve") {
                let bind = m.get_one::<String>("bind").cloned().unwrap_or_default();
                log_info!("marmite", "Starting built-in HTTP server...");
                crate::server::serve(&output_dir, &bind);
            } else if m.get_flag("watch") {
                crate::watch::watch(&input_dir, &output_dir, &config, force);
            }
        }
        Err(e) => {
            log_error!("marmite", "{}", e);
            std::process::exit(1);
        }
    }
}

