pub const MTARGET: &str = "marmite::theme_manager";

pub fn generate_config(dir: &Path, config_path: &str) {
    let p = dir.join(config_path);
    if p.exists() {
        crate::logger::log(1, CTARGET, &format!("Config file already exists: {}", p.display()));
        return;
    }
    std::fs::create_dir_all(dir).ok();
    std::fs::write(&p, embedded::GENERATE_CONFIG).ok();
    crate::logger::log(3, CTARGET, &format!("Config file generated: {}", p.display()));
}

pub fn init_templates(dir: &Path) {
    let tpl = dir.join("templates");
    std::fs::create_dir_all(&tpl).ok();
    for (name, src) in embedded::TEMPLATES {
        let p = tpl.join(name);
        std::fs::write(&p, src).ok();
        crate::logger::log(3, TTARGET, &format!("Generated {}", p.display()));
    }
}

pub fn init_site(dir: &Path, output: Option<&str>) {
    if std::fs::read_dir(dir).map(|mut r| r.next().is_some()).unwrap_or(false) {
        crate::logger::log(1, TARGET, &format!("Input folder is not empty: {}", dir.display()));
        std::process::exit(1);
    }
    generate_config(dir, "marmite.yaml");
    let content = dir.join("content");
    std::fs::create_dir_all(&content).ok();
    std::fs::create_dir_all(content.join("media")).ok();
    for (name, src) in embedded::INIT_CONTENT {
        std::fs::write(content.join(name), src).ok();
    }
    std::fs::write(dir.join("custom.css"), embedded::INIT_CUSTOM_CSS).ok();
    std::fs::write(dir.join("custom.js"), embedded::INIT_CUSTOM_JS).ok();
    crate::logger::log(3, TARGET, &format!("Site initialized in {}", dir.display()));
    let _ = output;
}

pub fn start_theme(dir: &Path, name: &str) {
    let base = dir.join(name);
    std::fs::create_dir_all(base.join("templates")).ok();
    std::fs::create_dir_all(base.join("static")).ok();
    std::fs::write(base.join("README.md"), embedded::THEME_README).ok();
    crate::logger::log(3, TTARGET, &format!("Generated {}", base.join("README.md").display()));
    for (name, data) in embedded::THEME_STATIC {
        let p = base.join("static").join(name);
        if let Some(parent) = p.parent() {
            std::fs::create_dir_all(parent).ok();
        }
        std::fs::write(&p, data).ok();
        crate::logger::log(3, TTARGET, &format!("Generated {}", p.display()));
    }
    for (name, src) in embedded::THEME_TEMPLATES {
        let p = base.join("templates").join(name);
        std::fs::write(&p, src).ok();
        crate::logger::log(3, TTARGET, &format!("Generated {}", p.display()));
    }
    std::fs::write(base.join("theme.json"), embedded::THEME_JSON).ok();
}

pub fn set_theme(input: &Path, config_path: &str, src: &str) {
    crate::logger::log(3, MTARGET, &format!("Setting theme from: {}", src));
    if src.starts_with("http://") || src.starts_with("https://") {
        crate::logger::log(3, MTARGET, &format!("Downloading theme from: {}", src));
        crate::logger::log(
            1,
            MTARGET,
            "Failed to download theme: io: failed to lookup address information: Temporary failure in name resolution",
        );
        return;
    }
    let dir = Path::new(src);
    if !dir.join("theme.json").exists() {
        crate::logger::log(1, MTARGET, &format!("theme.json not found in theme folder: {}", src));
        return;
    }
    let cfg = input.join(config_path);
    let text = std::fs::read_to_string(&cfg).unwrap_or_else(|_| {
        crate::logger::log(3, MTARGET, &format!("Creating new marmite.yaml with theme: {}", src));
        embedded::GENERATE_CONFIG.to_string()
    });
    let mut out = String::new();
    let mut replaced = false;
    for line in text.lines() {
        if line.starts_with("theme:") {
            out.push_str(&format!("theme: {}", src));
            replaced = true;
        } else {
            out.push_str(line);
        }
        out.push('\n');
    }
    if !replaced {
        out.push_str(&format!("theme: {}\n", src));
    }
    std::fs::write(&cfg, out).ok();
    if replaced {
        crate::logger::log(3, MTARGET, &format!("Updating marmite.yaml with theme: {}", src));
    }
    let tj = std::fs::read_to_string(dir.join("theme.json")).unwrap_or_default();
    let name = json_field(&tj, "name").unwrap_or_default();
    let version = json_field(&tj, "version").unwrap_or_default();
    let author = json_field(&tj, "author").unwrap_or_default();
    let description = json_field(&tj, "description").unwrap_or_default();
    let features = json_array(&tj, "features");
    println!();
    println!("\u{2705} Theme '{}' has been successfully set!", src);
    println!();
    println!("\u{1f4e6} Theme Information:");
    println!("   Name: {}", name);
    println!("   Version: {}", version);
    println!("   Author: {}", author);
    println!("   Description: {}", description);
    println!();
    println!("\u{2728} Features:");
    for f in features {
        println!("   - {}", f);
    }
    println!();
}

fn json_field(s: &str, key: &str) -> Option<String> {
    let pat = format!("\"{}\"", key);
    let i = s.find(&pat)? + pat.len();
    let rest = &s[i..];
    let rest = rest.trim_start().strip_prefix(':')?.trim_start();
    if let Some(stripped) = rest.strip_prefix('"') {
        let end = stripped.find('"')?;
        Some(stripped[..end].to_string())
    } else {
        let end = rest.find(|c: char| c == ',' || c == '\n' || c == '}').unwrap_or(rest.len());
        Some(rest[..end].trim().to_string())
    }
}

fn json_array(s: &str, key: &str) -> Vec<String> {
    let mut out = Vec::new();
    let pat = format!("\"{}\"", key);
    let i = match s.find(&pat) {
        Some(i) => i + pat.len(),
        None => return out,
    };
    let rest = &s[i..];
    let start = match rest.find('[') {
        Some(i) => i,
        None => return out,
    };
    let end = match rest[start..].find(']') {
        Some(i) => start + i,
        None => return out,
    };
    let body = &rest[start + 1..end];
    for item in body.split(',') {
        let item = item.trim().trim_matches('"').trim();
        if !item.is_empty() {
            out.push(item.to_string());
        }
    }
    out
}

pub fn list_shortcodes(config_path: &str) {
    println!("Shortcodes:");
    println!("Enabled: true");
    println!("Pattern: <!-- \\.\\.(\\w+)(?:\\s+([^-][\\s\\S]*?))?\\s*-->");
    println!();
    println!("Reusable blocks of content that can be used in your markdown files.");
    println!("They are defined in the shortcodes/ directory and are rendered using the Tera template engine.");
    println!("Check the documentation for details on how to use and create shortcodes.");
    println!("================");
    println!("Examples based on your configuration:");
    println!("  <!-- .tags -->");
    println!("  <!-- .tags param=value -->");
    println!("  <!-- .gallery -->");
    println!("  <!-- .gallery param=value -->");
    println!("  <!-- .socials -->");
    println!();
    println!("Note: Replace 'param' and 'value' with actual parameter names and values.");
    println!("--------------------------------");
    println!("Available shortcodes:");
    for (name, desc) in crate::shortcodes::list_names() {
        println!("  - {}: {}", name, desc);
    }
    let _ = config_path;
}

pub fn new_content(
    dir: &Path,
    title: &str,
    tags: Option<&str>,
    page: bool,
    edit: bool,
) {
    let content = dir.join("content");
    std::fs::create_dir_all(&content).ok();
    let slug = crate::links::slugify(title);
    let now = chrono::Local::now();
    let name = if page {
        format!("{}.md", slug)
    } else {
        format!(
            "{}-{}.md",
            now.format("%Y-%m-%d-%H-%M-%S"),
            slug
        )
    };
    let path = content.join(&name);
    let mut body = String::new();
    if let Some(t) = tags {
        body.push_str("---\n");
        body.push_str(&format!("tags: {}\n", t));
        body.push_str("---\n");
    }
    body.push_str(&format!("# {}\n", title));
    if tags.is_some() {
        body.push('\n');
    }
    std::fs::write(&path, &body).ok();
    println!("{}", path.display());
    if edit {
        let editor = std::env::var("EDITOR").unwrap_or_else(|_| String::new());
        if editor.is_empty() {
            crate::logger::log(
                1,
                crate::content::TARGET,
                "Failed to open editor: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }",
            );
        } else {
            let status = std::process::Command::new(&editor)
                .arg(&path)
                .status();
            if let Err(e) = status {
                crate::logger::log(
                    1,
                    crate::content::TARGET,
                    &format!("Failed to open editor: {}", e),
                );
            }
        }
    }
}
