pub fn new_content(
    dir: &Path,
    title: &str,
    tags: Option<&str>,
    page: bool,
    edit: bool,
) {
    let content = dir.join("content");
    std::fs::create_dir_all(&content).ok();
    let slug = crate::links::slugify(title);
    let now = chrono::Local::now();
    let name = if page {
        format!("{}.md", slug)
    } else {
        format!(
            "{}-{}.md",
            now.format("%Y-%m-%d-%H-%M-%S"),
            slug
        )
    };
    let path = content.join(&name);
    let mut body = String::new();
    if let Some(t) = tags {
        body.push_str("---\n");
        body.push_str(&format!("tags: {}\n", t));
        body.push_str("---\n");
    }
    body.push_str(&format!("# {}\n", title));
    if tags.is_some() {
        body.push('\n');
    }
    std::fs::write(&path, &body).ok();
    println!("{}", path.display());
    if edit {
        let editor = std::env::var("EDITOR").unwrap_or_else(|_| String::new());
        if editor.is_empty() {
            crate::logger::log(
                1,
                crate::content::TARGET,
                "Failed to open editor: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }",
            );
        } else {
            let status = std::process::Command::new(&editor)
                .arg(&path)
                .status();
            if let Err(e) = status {
                crate::logger::log(
                    1,
                    crate::content::TARGET,
                    &format!("Failed to open editor: {}", e),
                );
            }
        }
    }
}
