// Simple polling file watcher with rebuilds.
use crate::config::Marmite;
use std::path::Path;

pub fn snapshot(dir: &Path) -> Vec<(std::path::PathBuf, i64)> {
    let mut out = Vec::new();
    walk(dir, &mut out);
    out
}

fn walk(dir: &Path, out: &mut Vec<(std::path::PathBuf, i64)>) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() {
                let name = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
                if name.starts_with('.') || name == "site" {
                    continue;
                }
                walk(&p, out);
            } else {
                let m = e
                    .metadata()
                    .ok()
                    .and_then(|m| m.modified().ok())
                    .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                    .map(|d| d.as_secs() as i64)
                    .unwrap_or(0);
                out.push((p, m));
            }
        }
    }
}

pub fn watch(input: &Path, output: &Path, config: &Marmite, force: bool) {
    let mut prev = snapshot(input);
    loop {
        std::thread::sleep(std::time::Duration::from_millis(1000));
        let cur = snapshot(input);
        if cur != prev {
            prev = cur;
            let _ = crate::build::run(input, output, config, force, false);
        }
    }
}
