cd /tmp/marmite && python3 - <<'PY'
p='src/dates.rs'
s=open(p).read()
s=s.replace("""pub fn format_naive(s: &str, fmt: &str) -> String {
    match parse_naive(s) {
        Some(dt) => dt.format(fmt).to_string(),
        None => String::new(),
    }
}""","""pub fn format_naive(s: &str, fmt: &str) -> String {
    let dt = match parse_naive(s) {
        Some(d) => d,
        None => return String::new(),
    };
    // chrono's %+ needs an offset; the reference treats naive values as UTC
    if fmt.contains("%+") {
        let replaced = fmt.replace("%+", "%Y-%m-%dT%H:%M:%S");
        return format!("{}+00:00", dt.format(&replaced).to_string());
    }
    dt.format(fmt).to_string()
}""")
open(p,'w').write(s)
