{"command": "cd /tmp/marmite && cat >> src/build.rs <<'RSEOF'

pub fn rss_date(dt: &chrono::NaiveDateTime) -> String {
    use chrono::Timelike;
    let days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let months = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    let wd = days[dt.weekday().num_days_from_sunday() as usize];
    format!(
        "{}, {:02} {} {:02} {:02}:{:02}:{:02} GMT",
        wd,
        dt.day(),
        months[(dt.month() - 1) as usize],
        dt.year(),
        dt.hour(),
        dt.minute(),
        dt.second()
    )
}

pub fn html_escape_attr(s: &str) -> String {
    crate::markdown::escape_html(s)
}

impl<'a> Build<'a> {
    pub fn render_group(&self, kind: &str, name: &str, items: &[Content]) -> Value {
        Value::Array(vec![
            Value::Str(name.to_string()),
            Value::Array(items.iter().map(crate::site::content_to_value).collect()),
        ])
    }

    pub fn build_feeds(&mut self) {
        let base = base_url(self.config);
        let groups: Vec<(&str, String, String, Vec<Content>, &str)> = vec![];
        let _ = groups;
        let mut feeds: Vec<(String, String, String, Vec<Content>)> = Vec::new();
        feeds.push(("index.rss".to_string(), "index".to_string(), "index".to_string(), self.posts.iter().filter(|c| c.stream.is_none()).cloned().collect()));
        for (name, items) in self.tag.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("tag-{}.rss", slug), format!("tag: {}", name), slug, items));
        }
        for (name, items) in self.stream.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("{}.rss", slug), name.clone(), slug, items));
        }
        for (name, items) in self.series.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("series-{}.rss", slug), name.clone(), slug, items));
        }
        for (name, items) in self.author.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("author-{}.rss", slug), format!("author: {}", name), slug, items));
        }
        for (name, items) in self.archive.clone() {
            feeds.push((format!("archive-{}.rss", name), format!("year: {}", name), name.clone(), items));
        }
        for (file, title, group, items) in feeds {
            let items: Vec<Content> = items
                .into_iter()
                .filter(|c| c.stream.as_deref() != Some("draft"))
                .take(15)
                .collect();
            let latest = items
                .first()
                .and_then(|c| c.date.clone())
                .map(|d| crate::dates::parse_naive(&d))
                .flatten();
            let mut xml = String::new();
            xml.push_str("<?xml version=\"1.0\" encoding=\"utf-8\"?><rss version=\"2.0\" xmlns:content=\"http://purl.org/rss/1.0/modules/content/\"><channel>");
            xml.push_str(&format!("<title>{}</title>", html_escape_attr(&self.config.name)));
            xml.push_str(&format!("<link>{}</link>", html_escape_attr(&base)));
            xml.push_str(&format!("<description>{}</description>", html_escape_attr(&self.config.tagline)));
            if let Some(d) = latest {
                xml.push_str(&format!("<pubDate>{}</pubDate>", rss_date(&d)));
            }
            xml.push_str(&format!("<lastBuildDate>{}</lastBuildDate>", rss_date(&self.now.naive_utc())));
            xml.push_str("<generator>marmite</generator>");
            for c in &items {
                let link = format!("{}{}.html", base, c.slug);
                xml.push_str(&format!(
                    "<item><title>{}</title><link>{}</link>",
                    html_escape_attr(&c.title),
                    html_escape_attr(&link)
                ));
                if let Some(t) = c.tags.first() {
                    xml.push_str(&format!("<category>{}</category>", html_escape_attr(t)));
                }
                xml.push_str(&format!("<guid>{}</guid>", html_escape_attr(&link)));
                if let Some(d) = &c.date {
                    if let Some(dt) = crate::dates::parse_naive(d) {
                        xml.push_str(&format!("<pubDate>{}</pubDate>", rss_date(&dt)));
                    }
                }
                xml.push_str(&format!(
                    "<source url=\"{}\">{}</source>",
                    html_escape_attr(&base),
                    html_escape_attr(&group)
                ));
                xml.push_str(&format!(
                    "<content:encoded><![CDATA[{}]]></content:encoded></item>",
                    c.html
                ));
            }
            xml.push_str("</channel></rss>");
            let path = self.output.join(&file);
            write_file(&path, &xml);
            crate::logger::log(3, "marmite::feed", &format!("Generated {}", path.display()));
            self.urls.feeds.push(file.clone());
            if self.config.json_feed {
                let mut json = String::new();
                json.push_str("{\n  \"version\": \"https://jsonfeed.org/version/1\",\n");
                json.push_str(&format!("  \"title\": {},\n", serde_json::to_string(&self.config.name).unwrap_or_default()));
                json.push_str(&format!("  \"home_page_url\": {},\n", serde_json::to_string(&base).unwrap_or_default()));
                let jf = file.replace(".rss", ".json");
                json.push_str(&format!("  \"feed_url\": {},\n", serde_json::to_string(&format!("/{}", jf)).unwrap_or_default()));
                json.push_str(&format!("  \"description\": {},\n", serde_json::to_string(&self.config.tagline).unwrap_or_default()));
                json.push_str("  \"items\": [");
                for (i, c) in items.iter().enumerate() {
                    if i > 0 {
                        json.push(',');
                    }
                    let d = c
                        .date
                        .clone()
                        .map(|x| x.replace(' ', "T") + "-00:00")
                        .unwrap_or_default();
                    json.push_str(&format!(
                        "\n    {{\n      \"id\": {},\n      \"url\": {},\n      \"title\": {},\n      \"content_html\": {},\n      \"summary\": \"\",\n      \"date_published\": {},\n      \"image\": \"\",\n      \"authors\": [],\n      \"tags\": [{}],\n      \"language\": {}\n    }}",
                        serde_json::to_string(&format!("/{}.html", c.slug)).unwrap_or_default(),
                        serde_json::to_string(&format!("{}{}.html", base, c.slug)).unwrap_or_default(),
