pub fn rss_date(dt: &chrono::NaiveDateTime) -> String {
    use chrono::Timelike;
    let days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let months = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    let wd = days[dt.weekday().num_days_from_sunday() as usize];
    format!(
        "{}, {:02} {} {:02} {:02}:{:02}:{:02} GMT",
        wd,
