        for (name, items) in self.tag.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("tag-{}.rss", slug), format!("tag: {}", name), slug, items));
        }
        for (name, items) in self.stream.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("{}.rss", slug), name.clone(), slug, items));
        }
        for (name, items) in self.series.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("series-{}.rss", slug), name.clone(), slug, items));
        }
        for (name, items) in self.author.clone() {
            let slug = crate::links::slugify(&name);
            feeds.push((format!("author-{}.rss", slug), format!("author: {}", name), slug, items));
        }
        for (name, items) in self.archive.clone() {
