pub fn indent_json(s: &str) -> String {
    let mut out = String::new();
    let mut depth = 0;
    let mut in_str = false;
    let mut esc = false;
    for c in s.chars() {
        if in_str {
            out.push(c);
            if esc {
                esc = false;
            } else if c == '\\\\' {
                esc = true;
            } else if c == '"' {
                in_str = false;
            }
            continue;
        }
        match c {
            '"' => {
                in_str = true;
                out.push(c);
            }
            '{' | '[' => {
                depth += 1;
                out.push(c);
            }
            '}' | ']' => {
                depth -= 1;
                out.push(c);
            }
            ',' => {
                out.push(c);
            }
            ':' => {
                out.push_str(": ");
            }
            _ => out.push(c),
        }
    }
    out
}
